    const variant = isShort ? 2 : (seed < 0.48 ? 0 : 1);
    const matVal = (variant === 1 || variant === 2) ? 1.0 : 0.0;

    // ---------------------------------------------------------------------
    // ВАРИАНТ 2 — ПЛОСКИЙ (теперь с адекватными размерами)
    // ---------------------------------------------------------------------
