        const bLT = [b.wx + px*hw, b.yBot, b.wz + pz*hw];
        const aLB = [a.wx + px*hw, a.ySpand, a.wz + pz*hw];
        const bLB = [b.wx + px*hw, b.ySpand, b.wz + pz*hw];
        pushQuad(aLT, bLT, bLB, aLB, -sa, 0, ca, 1.0);

