        const bRT = [b.wx - px*hw, b.yBot, b.wz - pz*hw];
        const aRB = [a.wx - px*hw, a.ySpand, a.wz - pz*hw];
        const bRB = [b.wx - px*hw, b.ySpand, b.wz - pz*hw];
