function computeMorphologicalBathymetry(area, S, riverFeatures, waterPolygons, streamScale = 1.0) {
  const { Nx, Ny, cls, distWater, height, hMin } = S;
  const cellM = area.cellM;
  const N = Nx * Ny;
  const bathy = new Float32Array(N);

  // 1. Оценка среднего уклона берегов вокруг водоёмов
  const shoreSlope = new Float32Array(N);
  for (let j = 1; j < Ny - 1; j++) {
    for (let i = 1; i < Nx - 1; i++) {
      const k = j * Nx + i;
      if (distWater[k] === 0) { // Только суша у береговой кромки
        const dhx = (height[k + 1] - height[k - 1]) / (2 * cellM);
        const dhy = (height[k + Nx] - height[k - Nx]) / (2 * cellM);
        shoreSlope[k] = Math.hypot(dhx, dhy);
      }
    }
  }

  // Размываем уклон вглубь воды, чтобы чаша знала крутизну окружающих склонов
  const meanSlope = boxBlurF(shoreSlope, Nx, Ny, Math.max(2, Math.round(60 / cellM)));

  // 2. Расчет чаш озер, карьеров и заливов
  for (let i = 0; i < N; i++) {
    const c = cls[i];
    const isWater = (c === CLS_WATER);
    const isSwamp = (c === 23 || c === 24 || c === 25 || c === 28);

    if (!isWater && !isSwamp) {
      bathy[i] = 0.0;
      continue;
    }

    const distM = distWater[i] * cellM; // Удаление от берега в метрах
    const localSlope = Math.max(0.04, meanSlope[i]);

    if (isSwamp) {
      // Болота: мелководная линза 0.2 - 0.7 м
      bathy[i] = 0.15 + 0.55 * (1.0 - Math.exp(-distM / 15.0));
      continue;
    }

    // Озера: параболоидная чаша, крутизна свала зависит от берега
    const estMaxDepth = Math.min(45.0, Math.pow(distM, 0.52) * Math.pow(localSlope * 10.0, 0.45) * 1.8 + 1.8);
    const dDrop = Math.max(8.0, 35.0 / (localSlope * 3.0 + 1.0));
    let dBowl = estMaxDepth * (1.0 - Math.exp(-Math.pow(distM / dDrop, 0.95)));

    // Естественный микрорельеф дна (банки, отмели)
    const wx = (i % Nx) * cellM;
    const wz = Math.floor(i / Nx) * cellM;
    const bedRoughness = (vnoise(wx * 0.015, wz * 0.015) - 0.5) * (dBowl * 0.2);
    dBowl = Math.max(0.2, dBowl + bedRoughness);

    bathy[i] = dBowl;
  }

  // 3. Формирование русла рек и ручьев (непрерывная растеризация по 2D BBox)
  if (riverFeatures && riverFeatures.length) {
    const fx = Nx / area.widthM;
    const fy = Ny / area.heightM;

    riverFeatures.forEach(feat => {
      const p = feat.props || {};
      const k = p.kind || p.class || p.type || p.waterway || '';
      
      let w = 4.5 * streamScale;
      let maxRiverD = 0.9;
      if (k === 'river')        { w = 22.0 * streamScale; maxRiverD = 3.2; }
      else if (k === 'canal')   { w = 12.0 * streamScale; maxRiverD = 2.2; }
      else if (k === 'stream')  { w = 6.0  * streamScale; maxRiverD = 1.2; }

      const halfW = w * 0.5;

      feat.geom.forEach(line => {
        for (let idx = 0; idx < line.length - 2; idx += 2) {
          const x1 = line[idx],     z1 = line[idx + 1];
          const x2 = line[idx + 2], z2 = line[idx + 3];

          const segLen = Math.hypot(x2 - x1, z2 - z1);
          if (segLen < 0.1) continue;
          const nx = (x2 - x1) / segLen;
          const nz = (z2 - z1) / segLen;

          // Охватывающий прямоугольник (BBox) всего сегмента
          const minX = Math.min(x1, x2) - halfW;
          const maxX = Math.max(x1, x2) + halfW;
          const minZ = Math.min(z1, z2) - halfW;
          const maxZ = Math.max(z1, z2) + halfW;

          const ix0 = clamp(Math.floor((minX - (-area.widthM * 0.5)) * fx), 0, Nx - 1);
          const ix1 = clamp(Math.ceil((maxX - (-area.widthM * 0.5)) * fx), 0, Nx - 1);
          const iz0 = clamp(Math.floor((minZ - (-area.heightM * 0.5)) * fy), 0, Ny - 1);
          const iz1 = clamp(Math.ceil((maxZ - (-area.heightM * 0.5)) * fy), 0, Ny - 1);

          for (let iz = iz0; iz <= iz1; iz++) {
            const pz = (iz / (Ny - 1) - 0.5) * area.heightM;
            for (let ix = ix0; ix <= ix1; ix++) {
              const px = (ix / (Nx - 1) - 0.5) * area.widthM;

              const vx = px - x1, vz = pz - z1;
              const t = clamp((vx * nx + vz * nz) / segLen, 0.0, 1.0);
              const projX = x1 + nx * t * segLen;
              const projZ = z1 + nz * t * segLen;

              const dist = Math.hypot(px - projX, pz - projZ);
              if (dist <= halfW) {
                const perpNorm = dist / halfW;
                // Параболическое U-образное русло
                const uShape = Math.max(0.0, 1.0 - perpNorm * perpNorm);
                const rDepth = maxRiverD * uShape;
                const cellIdx = iz * Nx + ix;
                bathy[cellIdx] = Math.max(bathy[cellIdx], rDepth);
              }
            }
          }
        }
      });
    });
  }

  // 4. Мягкое сглаживание дна для устранения ступеней
  return boxBlurF(bathy, Nx, Ny, 1);


}

// ===========================================================================
// СКАЛЫ, ЧАСТЬ 1: «запечённая» резьба рельефа (ярусы + промоины)
// ===========================================================================
const STRATA_M = 10; // период слоистости, м (общий для CPU и шейдеров)

function carveRockRelief(S, area, opt) {
  opt = opt || {};
  if (area.isMacro) return;
  const { Nx, Ny, cls, rockPeak, height } = S;
  const cellM = area.cellM;
  if (cellM > 40) return;                      // на грубой сетке смысла нет

  const src = new Float32Array(height);        // исходник, чтобы не накапливать
  const cx = S.W / (Nx - 1), cz = S.H / (Ny - 1);
  const amp   = (opt.amp != null ? opt.amp : 1.0) * clamp(cellM * 0.45, 0.6, 6.0); // глубина промоин, м
  const layer = STRATA_M * Math.max(1, Math.round(cellM / STRATA_M));              // шаг уступов, м
  const terr  = opt.terrace != null ? opt.terrace : 0.55;                          // сила «лестницы»

  let hMin = S.hMin, hMax = S.hMax;
  for (let j = 1; j < Ny - 1; j++) {
    for (let i = 1; i < Nx - 1; i++) {
      const k = j * Nx + i;
      const rp = rockPeak[k];
      if (rp < 0.2 || cls[k] === CLS_WATER) continue;
      if (S.roadMask && S.roadMask[k] > 20) continue;

      const dhx = (src[k + 1] - src[k - 1]) / (2 * cx);
      const dhz = (src[k + Nx] - src[k - Nx]) / (2 * cz);
      const ts = Math.hypot(dhx, dhz);
      const m = smooth(0.2, 0.7, rp) * smooth(0.25, 0.8, ts + rp * 0.3);
      if (m < 0.02) continue;

      const wx = (i / (Nx - 1) - 0.5) * S.W, wz = (j / (Ny - 1) - 0.5) * S.H;

      // 1) промоины/кулуары (ridged-шум в двух масштабах)
      const g1 = 1 - Math.abs(2 * vnoise(wx * 0.012 + 11.3, wz * 0.012 + 4.1) - 1);
      const g2 = 1 - Math.abs(2 * vnoise(wx * 0.035 + 3.7,  wz * 0.035 + 9.9) - 1);
      const ridge = g1 * g1 * 0.65 + g2 * g2 * 0.35;
      let h = src[k] + (ridge - 0.45) * amp * (0.5 + Math.min(ts, 1.5)) * m;

      // 2) ярусы: плоские полки + крутые уступы, фаза плавает по шуму
      const warp = (vnoise(wx * 0.006 + 1.7, wz * 0.006 + 8.3) - 0.5) * 0.9;
      const t = h / layer + warp, fl = Math.floor(t), fr = t - fl;
      const stepped = (fl + smooth(0.15, 0.85, fr) - warp) * layer;
      h = lerp(h, stepped, terr * m * smooth(0.5, 1.1, ts));

      height[k] = h;
      if (h < hMin) hMin = h; else if (h > hMax) hMax = h;
    }
  }
  S.hMin = hMin; S.hMax = hMax; S.relief = Math.max(hMax - hMin, 1.0);
}


  function composeScene(area, hub, opt) {
    const { Nx, Ny } = area, N = Nx * Ny, src = hub.sources;
    const ok = id => src[id].state === 'ok' && src[id].data;
    const S = { area, Nx, Ny, W: area.widthM, H: area.heightM, used: {}, notes: [] };

    // Привязка спутниковой подложки к сцене
    S.basemapCanvas = ok('basemap') ? src.basemap.data : null;

    // Параметры дорог и рек
    const roadScale = (opt && opt.view && opt.view.roadWidth) || 1.0;
    const vData = ok('vectors') ? src.vectors.data : null;
    const streamOpt = {
      streams: (opt && opt.view && opt.view.streams !== false),
      streamWidth: (opt && opt.view && opt.view.streamWidth) || 1.0
    };

    let waterCv = null;
    if (vData && ((vData.waterPolygons && vData.waterPolygons.length) || (vData.riverFeatures && vData.riverFeatures.length))) {
      waterCv = createWaterFlowTexture(area, vData.waterPolygons, vData.riverFeatures, streamOpt);
    }
    if (!waterCv) {
      waterCv = document.createElement('canvas');
      waterCv.width = Nx; waterCv.height = Ny;
      const wInitCtx = waterCv.getContext('2d');
      wInitCtx.fillStyle = 'rgba(128, 128, 0, 0)';
      wInitCtx.fillRect(0, 0, Nx, Ny);
    }
    S.waterFlowCanvas = waterCv;

    const osmWater = new Uint8Array(N);
    if (waterCv) {
      const wOsm = waterCv.getContext('2d').getImageData(0, 0, Nx, Ny).data;
      for (let i = 0; i < N; i++) if (wOsm[i * 4 + 3] > 140) osmWater[i] = 1;
    }


    // ВАЖНО: Запекаем маску дорог и фундаментов для шейдера земли и очистки деревьев
    S.roadMask = (vData && ((vData.streetFeatures && vData.streetFeatures.length) || (vData.buildingFeatures && vData.buildingFeatures.length)))
      ? createObstaclesMask(area, vData.streetFeatures, vData.buildingFeatures, roadScale)
      : null;

    // Величина паводка
    let floodDeltaH = (opt && opt.view && opt.view.floodRise != null) ? opt.view.floodRise : 0.0;
    if (ok('water') && src.water.data && (!opt || opt.view.floodRise == null)) {
      const f = src.water.data;
      if (f.level === 'critical') floodDeltaH = 1.6;
      else if (f.level === 'high') floodDeltaH = 0.8;
      else if (f.level === 'elevated') floodDeltaH = 0.3;
    }
    S.floodDeltaH = floodDeltaH;

    S.demOk = !!ok('dem');
    S.height = S.demOk ? new Float32Array(src.dem.data.height) : new Float32Array(N);

    S.lcOk = !!ok('landcover'); S.canOk = !!ok('canopy'); S.osmOk = !S.lcOk && !!ok('osm');

    const cls = new Uint8Array(N), can = new Uint8Array(N);
    if (S.canOk) can.set(src.canopy.data.can);
    if (S.lcOk) cls.set(src.landcover.data.cls);
    const rnd = mulberry32(hashStr(area.key));
    const osm = S.osmOk ? src.osm.data : null;
    let osmForest = 14;
    if (osm) osmForest = osm.leaf === 'needleleaved' ? 10 : osm.leaf === 'broadleaved' ? 8 : 14;
    const osmGround = osm ? (osm.farm ? 1 : osm.wetland ? (osm.wetland === 'marsh' ? 24 : 23) : osm.heath || osm.scrub ? 15 : osm.grass ? 18 : osm.urban ? 30 : osm.sand ? 33 : osm.rock ? 32 : 0) : 0;

    const absLat = Math.abs((area && area.latC) || 45);
    const treelineM = clamp(4300 - absLat * 52, 450, 4000);

    // 1) Заполняем пропуски c === 0
    for (let i = 0; i < N; i++) {
      let c = cls[i];
      const h = can[i] / 4;
      if (c === 0) {
        if (S.demOk && S.height[i] <= 0.45 && h < 1) c = CLS_WATER;
        else if (osm) c = h >= 3 ? osmForest : (osmGround || (osm.forest ? osmForest : 18));
        else if (S.canOk && h >= 3) c = 14;
        cls[i] = c;
      }
    }

    // 2) Убираем ложную горную воду и «асфальт» по уклонам DEM
    sanitizeMountainLandcover(area, S, cls, can, osmWater, S.roadMask, treelineM);

    // 3) Обнуляем кроны на реальной воде и достраиваем условные кроны там, где нет Canopy Height
    for (let i = 0; i < N; i++) {
      const c = cls[i];
      if (c === CLS_WATER) can[i] = 0;
      if (!S.canOk && LC[c].group === 2) {
        const base = LC[c].open ? 9 : 16;
        can[i] = Math.round(base * (0.75 + 0.5 * rnd()) * 4);
      }
    }

    if (waterCv) {
      const wCtx = waterCv.getContext('2d');
      const wImg = wCtx.getImageData(0, 0, Nx, Ny);
      const wd = wImg.data;
      let cleared = 0;
      for (let i = 0; i < N; i++) {
        // Если это растровый водоём (класс 34), но в текстуре потока записан ручей (B > 0)
        if (cls[i] === CLS_WATER && wd[i * 4 + 2] > 0) {
          // Обнуляем вектор потока: R=128, G=128 (нулевое направление), B=0 (нулевая скорость)
          wd[i * 4]     = 128;
          wd[i * 4 + 1] = 128;
          wd[i * 4 + 2] = 0;
          cleared++;
        }
      }
      if (cleared) {
        wCtx.putImageData(wImg, 0, 0);
        console.log(`[Slice3D] Обнулён поток ручьёв над ${cleared} пикс. растровых водоёмов`);
      }
    }

    // Применение маски воды из векторов: срезаем кроны ТОЛЬКО в широких полигонах и реках
    if (waterCv) {
      const wCtx = waterCv.getContext('2d');
      const wPix = wCtx.getImageData(0, 0, Nx, Ny).data;
      for (let i = 0; i < N; i++) {
        if (wPix[i * 4 + 3] > 140) { // Высокий порог: только чистое зеркало воды
          cls[i] = CLS_WATER;
          can[i] = 0; // Убираем деревья из русла
        }
      }
    }

    if (S.demOk && (!opt || !opt.view || (opt.view.roads !== false && opt.view.roadFlatten !== false)) &&
        vData && vData.streetFeatures && vData.streetFeatures.length) {
      flattenRoadsTerrain(area, S.height, cls, vData.streetFeatures, roadScale);
    }

    // =========================================================================
    // ФИЗИЧЕСКИ КОРРЕКТНЫЙ ПАВОДОК (БЕЗ ЛАВИННОГО ЭФФЕКТА И БЕЗ ЗАТОПЛЕНИЯ ГОР)
    // =========================================================================
    if (S.demOk && S.floodDeltaH > 0.05) {
      const floodRise = S.floodDeltaH;
      const origHeight = new Float32Array(S.height);
      const origCls = new Uint8Array(cls);

      // 1. Приподнимаем уровень зеркала только у исходных водоёмов
      for (let i = 0; i < N; i++) {
        if (origCls[i] === CLS_WATER) {
          S.height[i] += floodRise;
        }
      }

      // 2. Локальное затопление поймы (считываем из неизменяемого origHeight/origCls)
      for (let j = 0; j < Ny; j++) {
        for (let i = 0; i < Nx; i++) {
          const k = j * Nx + i;
          if (origCls[k] === CLS_WATER) continue;

          let maxInundationLevel = -Infinity;
          let isFlatShore = false;

          // Опрашиваем исходных соседей
          for (let dy = -1; dy <= 1; dy++) {
            for (let dx = -1; dx <= 1; dx++) {
              if (dx === 0 && dy === 0) continue;
              const ni = i + dx, nj = j + dy;
              if (ni >= 0 && ni < Nx && nj >= 0 && nj < Ny) {
                const nk = nj * Nx + ni;
                if (origCls[nk] === CLS_WATER) {
                  const waterSurface = origHeight[nk] + floodRise;
                  // Проверяем, что берег пологий (не скала и не горный обрыв): разница высот с водой < 4м
                  if (origHeight[k] >= origHeight[nk] - 0.5 && origHeight[k] <= origHeight[nk] + 4.0) {
                    if (waterSurface > maxInundationLevel) {
                      maxInundationLevel = waterSurface;
                      isFlatShore = true;
                    }
                  }
                }
              }
            }
          }

          // Затапливаем только если пологий берег оказался НИЖЕ поднявшегося уровня воды
          if (isFlatShore && origHeight[k] < maxInundationLevel) {
            cls[k] = CLS_WATER;
            S.height[k] = maxInundationLevel;
            can[k] = 0; // Затопленная пойма теряет низкую растительность
          }
        }
      }
    }

    S.cls = cls; 
    S.can = can;

    // Расчёт min/max высот строго после паводка на чистых данных
    let hMin = 1e9, hMax = -1e9;
    for (let i = 0; i < N; i++) {
      const v = S.height[i];
      if (v > -500 && v < 10000) {
        if (v < hMin) hMin = v;
        if (v > hMax) hMax = v;
      }
    }
    if (hMin >= 1e8) { hMin = 0; hMax = 10; }
    S.hMin = hMin; S.hMax = hMax; S.relief = Math.max(hMax - hMin, 1.0);

    const span = Math.max(S.W, S.H);
    const viewOpt = (opt && opt.view) || {};
    const zAuto = viewOpt.zAuto !== false;
    const zVal = viewOpt.z != null ? viewOpt.z : 3.0;
    S.zEff = zAuto ? clamp(0.045 * span / Math.max(S.relief, 20.0), 1.0, 4.5) : zVal;

    const showBridges = streamOpt.streams && (opt && opt.view && opt.view.bridges !== false);
    const bridgeScale = (opt && opt.view && opt.view.bridgeScale != null) ? opt.view.bridgeScale : 1.0;

    S.bridges = (showBridges && vData &&
             vData.streetFeatures && vData.streetFeatures.length &&
             vData.riverFeatures && vData.riverFeatures.length)
    ? findBridgeIntersections(vData.streetFeatures, vData.riverFeatures, S, roadScale, bridgeScale)
    : [];

    // Расчёт расстояний до берега для сглаживания пены и цвета воды
    const nearWaterMask = new Uint8Array(N);
    const BIG = 1e6;
    const SQ2 = 1.41421356; // Диагональный шаг для устранения квадратных ступеней

    // Дистанция ВНУТРИ воды
    const distWater = new Float32Array(N);
    for (let i = 0; i < N; i++) distWater[i] = cls[i] === CLS_WATER ? BIG : 0;
    
    // Прямой проход (сверху-вниз, слева-направо)
    for (let j = 0; j < Ny; j++) {
      for (let i = 0; i < Nx; i++) {
        const k = j * Nx + i;
        if (distWater[k] === 0) continue;
        let d = distWater[k];
        if (i > 0) d = Math.min(d, distWater[k - 1] + 1.0);
        if (j > 0) d = Math.min(d, distWater[k - Nx] + 1.0);
        if (i > 0 && j > 0) d = Math.min(d, distWater[k - Nx - 1] + SQ2);
        if (i < Nx - 1 && j > 0) d = Math.min(d, distWater[k - Nx + 1] + SQ2);
        distWater[k] = d;
      }
    }
    // Обратный проход (снизу-вверх, справа-налево)
    for (let j = Ny - 1; j >= 0; j--) {
      for (let i = Nx - 1; i >= 0; i--) {
        const k = j * Nx + i;
        if (distWater[k] === 0) continue;
        let d = distWater[k];
        if (i < Nx - 1) d = Math.min(d, distWater[k + 1] + 1.0);
        if (j < Ny - 1) d = Math.min(d, distWater[k + Nx] + 1.0);
        if (i < Nx - 1 && j < Ny - 1) d = Math.min(d, distWater[k + Nx + 1] + SQ2);
        if (i > 0 && j < Ny - 1) d = Math.min(d, distWater[k + Nx - 1] + SQ2);
        distWater[k] = d;
      }
    }

    // 2. Дистанция НА СУШЕ до воды (для отсечения деревьев у берега)
    const distLand = new Float32Array(N);
    for (let i = 0; i < N; i++) distLand[i] = cls[i] === CLS_WATER ? 0 : BIG;
    for (let j = 0; j < Ny; j++) {
      for (let i = 0; i < Nx; i++) {
        const k = j * Nx + i;
        if (distLand[k] === 0) continue;
        let d = distLand[k];
        if (i > 0) d = Math.min(d, distLand[k - 1] + 1.0);
        if (j > 0) d = Math.min(d, distLand[k - Nx] + 1.0);
        if (i > 0 && j > 0) d = Math.min(d, distLand[k - Nx - 1] + SQ2);
        if (i < Nx - 1 && j > 0) d = Math.min(d, distLand[k - Nx + 1] + SQ2);
        distLand[k] = d;
      }
    }
    for (let j = Ny - 1; j >= 0; j--) {
      for (let i = Nx - 1; i >= 0; i--) {
        const k = j * Nx + i;
        if (distLand[k] === 0) continue;
        let d = distLand[k];
        if (i < Nx - 1) d = Math.min(d, distLand[k + 1] + 1.0);
        if (j < Ny - 1) d = Math.min(d, distLand[k + Nx] + 1.0);
        if (i < Nx - 1 && j < Ny - 1) d = Math.min(d, distLand[k + Nx + 1] + SQ2);
        if (i > 0 && j < Ny - 1) d = Math.min(d, distLand[k + Nx - 1] + SQ2);
        distLand[k] = d;
      }
    }

    const cellM = area.cellM;
    // Увеличиваем протяжённость прибрежного градиента с 35 м до 140 м
    const SHORE_DISTANCE_M = 140.0;
    const shoreSdf = new Float32Array(N);
    for (let i = 0; i < N; i++) {
      const rawSdf = (distWater[i] - distLand[i]) * cellM / SHORE_DISTANCE_M;
      shoreSdf[i] = clamp(rawSdf, -1.0, 1.0); // -1 (суша) ... 0 (берег) ... +1 (вода)
      nearWaterMask[i] = (distLand[i] * cellM <= 22.0) ? 1 : 0;
    }
    // Увеличенный радиус сглаживания для полного устранения квадратности
    const shoreBlurR = cellM < 4 ? 5 : (cellM < 10 ? 3 : 2);
    const smoothSdf = boxBlurF(shoreSdf, Nx, Ny, shoreBlurR);
    S.nearWater = nearWaterMask;
    S.distLand = distLand;
    S.distWater = distWater; // сохраняем distWater в S для батиметрии

    // --- РАСЧЁТ БАТИМЕТРИИ (вызывается строго после формирования height, cls и distWater) ---
 const bathyDepth = computeMorphologicalBathymetry(
      area, S, 
      vData ? vData.riverFeatures : null, 
      vData ? vData.waterPolygons : null,
      streamOpt.streamWidth || 1.0
    );
    S.bathymetry = bathyDepth;

    // Запекаем глубину в альфа-канал текстуры потока (0..60 метров -> 0..255)
    const MAX_BATHY_M = 60.0;
    const wCtx = waterCv.getContext('2d');
    const wImg = wCtx.getImageData(0, 0, Nx, Ny);
    for (let i = 0; i < N; i++) {
      const dM = bathyDepth[i];
      const isW = (cls[i] === CLS_WATER || dM > 0.05);
      if (isW) {
        const effD = Math.max(0.35, dM);
        const dByte = clamp(Math.round((effD / MAX_BATHY_M) * 254) + 1, 1, 255);
        wImg.data[i * 4 + 3] = dByte;
        // Если это стоячее озеро без векторного направления, задаем нейтральный вектор
        if (wImg.data[i * 4] === 0 && wImg.data[i * 4 + 1] === 0) {
          wImg.data[i * 4] = 128;
          wImg.data[i * 4 + 1] = 128;
          wImg.data[i * 4 + 2] = 0;
        }
      } else {
        wImg.data[i * 4 + 3] = 0;
      }
    }
    wCtx.putImageData(wImg, 0, 0);

    // (Удален вредоносный блок S.height[k] -= depth, создававший отвесные рвы)

    
    // --- Высотная поясность и маска каменистых пиков (treeline / snowline / rockPeak) ---
    // --- Высотная поясность и маска каменистых пиков (treeline / snowline / rockPeak) ---
    const baseSnowlineM = treelineM + clamp(1050 - absLat * 7.5, 450, 1050);
    S.treelineM = treelineM;
    S.baseSnowlineM = baseSnowlineM;

    const rW = clamp(Math.round(80 / cellM), 2, 14);
    const rWide = clamp(Math.round(280 / cellM), 4, 32);
    const mean = boxBlurF(S.height, Nx, Ny, rW);
    const meanWide = boxBlurF(S.height, Nx, Ny, rWide);

    const rockPeakArr = new Float32Array(N);
    const extra = new Uint8Array(N * 4);
    const showRoads = opt && opt.view && opt.view.roads !== false;
    const cellX = S.W / Math.max(Nx - 1, 1);
    const cellZ = S.H / Math.max(Ny - 1, 1);

    for (let j = 0; j < Ny; j++) {
      const jU = Math.max(0, j - 1), jD = Math.min(Ny - 1, j + 1);
      for (let i = 0; i < Nx; i++) {
        const k = j * Nx + i;
        const iL = Math.max(0, i - 1), iR = Math.min(Nx - 1, i + 1);

        const dhx = (S.height[j * Nx + iR] - S.height[j * Nx + iL]) / (2 * cellX);
        const dhz = (S.height[jD * Nx + i] - S.height[jU * Nx + i]) / (2 * cellZ);
        const ts = Math.hypot(dhx, dhz);

        const conc = mean[k] - S.height[k];
        const concNorm = clamp(0.5 + conc / 5, 0, 1);
        const ridgeMacro = clamp((S.height[k] - meanWide[k]) / 55, 0, 1);
        const relH = S.relief > 120 ? clamp((S.height[k] - S.hMin) / S.relief, 0, 1) : 0;

        // Мировые координаты для органической модуляции (без привязки к пикселям сетки)
        const wx = (i / Math.max(Nx - 1, 1) - 0.5) * S.W;
        const wz = (j / Math.max(Ny - 1, 1) - 0.5) * S.H;
        const patchN = vnoise(wx * 0.0045 + 3.1, wz * 0.0045 + 7.7) * 0.65
                     + vnoise(wx * 0.014  + 1.3, wz * 0.014  + 5.2) * 0.35;

        const c = cls[k];
        const grp = LC[c] ? LC[c].group : 0;
        const isForestCls = (grp === 2);
        const isVegCls    = (grp === 1 || grp === 3 || grp === 4 || grp === 5);

        const bareHint = (c === 32 || c === 35) ? 1.0 :
                         (c === 31 || c === 33) ? 0.78 :
                         (c === 20 || c === 21 || c === 22 || c === 19) ? 0.32 : 0.0;

        // В ложбинах (conc > 0) граница леса и почвы поднимается выше, на гребнях — ниже
        const effElev = S.height[k] + (0.5 - concNorm) * 260.0 + (patchN - 0.5) * 240.0;

        // Выше границы леса скалы нарастают плавно (перевал + субальпийский пояс)
        const altFactor = smooth(treelineM - 180, treelineM + 480, effElev);

        // В реальных лесах скалы проступают только на крутых обрывах (~38°..54°), на открытых местах ~31°..48°
        const slopeLo = isForestCls ? 0.78 : (isVegCls ? 0.62 : 0.45);
        const slopeHi = isForestCls ? 1.35 : (isVegCls ? 1.15 : 0.92);
        const slopeRock = smooth(slopeLo, slopeHi, ts + (patchN - 0.5) * 0.16);

        // Острые гребни: срабатывают только на реально высоких, выпуклых и крутых ребрах
        const promRock = smooth(320, 850, S.relief)
                       * smooth(0.58, 0.94, relH + (patchN - 0.5) * 0.15)
                       * smooth(0.22, 0.75, ridgeMacro)
                       * Math.max(smooth(0.48, 0.95, ts), bareHint);

        // Лес (GLC_FCS30D) подавляет ложные оголения на умеренных склонах
        const vegShield = isForestCls ? 0.45 : (isVegCls ? 0.72 : 1.0);

        const rockPeak = (c === CLS_WATER) ? 0.0 : clamp(
          Math.max(
            altFactor * (isForestCls ? 0.75 : 1.0),
            slopeRock * vegShield,
            promRock * (isForestCls ? 0.65 : 1.0),
            bareHint * smooth(0.18, 0.58, ts + relH * 0.35 + (patchN - 0.5) * 0.2)
          ),
          0, 1
        );
        rockPeakArr[k] = rockPeak;

        // Мягкое снижение высоты крон к границе скал (вместо жёсткого сбривания)
        const canKeep = (1.0 - smooth(treelineM - 150, treelineM + 260, effElev)) *
                        (1.0 - smooth(0.75, 1.35, ts)) *
                        (1.0 - smooth(0.45, 0.92, rockPeak));
        if (canKeep < 0.99) can[k] = Math.round(can[k] * canKeep);

        extra[k * 4]     = Math.round((smoothSdf[k] * 0.5 + 0.5) * 255);
        extra[k * 4 + 1] = Math.round(concNorm * 255);
        extra[k * 4 + 2] = Math.round(rockPeak * 255);
        extra[k * 4 + 3] = (showRoads && S.roadMask) ? S.roadMask[k] : 0;
      }
    }


    S.rockPeak = rockPeakArr;
    S.extra = extra;
    if (!opt || !opt.view || opt.view.rockRelief !== false) carveRockRelief(S, area);

    // --- Выравнивание поверхности воды один раз на CPU (убирает цикл из VS_TERRAIN) ---
    {
      const cellM_w = Math.max(S.W / Math.max(Nx - 1, 1), S.H / Math.max(Ny - 1, 1));
      const maxStepM = 0.015 * cellM_w;
      const maxRiverStepM = 0.06 * cellM_w;
      const wPix = wImg.data;
      const hSrc = S.height;
      const hFlat = new Float32Array(hSrc);
      const DIRS = [[1, 0], [-1, 0], [0, 1], [0, -1]];
      const rivOff = [];
      for (let dy = -2; dy <= 2; dy++) {
        for (let dx = -2; dx <= 2; dx++) {
          if (dx === 0 && dy === 0) continue;
          rivOff.push([dx, dy, Math.hypot(dx, dy) * maxRiverStepM]);
        }
      }
      let hasWater = false;
      for (let j = 0; j < Ny; j++) {
        for (let i = 0; i < Nx; i++) {
          const k = j * Nx + i;
          if (cls[k] === CLS_WATER) hasWater = true;
          if (wPix[k * 4 + 3] <= 5) continue; // fl0.a <= 0.02
          hasWater = true;
          const h0 = hSrc[k];
          if (wPix[k * 4 + 2] < 38) { // fl0.b < 0.15 (стоячая вода)
            let hBest = h0;
            const sL = extra[(j * Nx + Math.max(0, i - 2)) * 4];
            const sR = extra[(j * Nx + Math.min(Nx - 1, i + 2)) * 4];
            const sD = extra[(Math.max(0, j - 2) * Nx + i) * 4];
            const sU = extra[(Math.min(Ny - 1, j + 2) * Nx + i) * 4];
            const gx = sR - sL, gz = sU - sD;
            const gl = Math.hypot(gx, gz);
            if (gl > 0.0255) { // 1e-4 * 255
              const dx = gx / gl, dz = gz / gl;
              let cx = i, cz = j;
              for (let st = 1; st <= 22; st++) {
                cx += dx; cz += dz;
                const px = Math.round(cx), pz = Math.round(cz);
                if (px < 0 || pz < 0 || px >= Nx || pz >= Ny) break;
                const pk = pz * Nx + px;
                if (wPix[pk * 4 + 3] <= 5 || wPix[pk * 4 + 2] >= 38) break;
                const cand = hSrc[pk] + st * maxStepM;
                if (cand < hBest) hBest = cand;
              }
            }
            for (let d = 0; d < 4; d++) {
              const ddx = DIRS[d][0], ddz = DIRS[d][1];
              for (let st = 1; st <= 8; st++) {
                const px = i + ddx * st, pz = j + ddz * st;
                if (px < 0 || pz < 0 || px >= Nx || pz >= Ny) break;
                const pk = pz * Nx + px;
                if (wPix[pk * 4 + 3] <= 5 || wPix[pk * 4 + 2] >= 38) break;
                const cand = hSrc[pk] + st * maxStepM;
                if (cand < hBest) hBest = cand;
              }
            }
            hFlat[k] = hBest;
          } else { // река / ручей
            let hRiver = h0;
            for (let r = 0; r < rivOff.length; r++) {
              const px = clamp(i + rivOff[r][0], 0, Nx - 1);
              const pz = clamp(j + rivOff[r][1], 0, Ny - 1);
              const pk = pz * Nx + px;
              if (wPix[pk * 4 + 3] > 5) {
                const cand = hSrc[pk] + rivOff[r][2];
                if (cand < hRiver) hRiver = cand;
              }
            }
            hFlat[k] = hRiver;
          }
        }
      }
      S.height.set(hFlat);
      S._hasWater = hasWater;
    }

    const counts = new Float64Array(40);
    for (let i = 0; i < N; i++) counts[cls[i]]++;
    S.counts = counts;
    S.stats = [];
    for (let c = 1; c < 40; c++) if (counts[c] / N > 0.004 && LC[c]) S.stats.push({ id: c, pct: counts[c] / N * 100 });
    S.stats.sort((a, b) => b.pct - a.pct);
    S.hasForest = S.stats.some(s => LC[s.id].group === 2);
    let canSum = 0, canCnt = 0;
    for (let i = 0; i < N; i++) {
      if (can[i] >= 12) { canSum += can[i] / 4; canCnt++; }
    }
    S.avgH = canCnt > 0 ? (canSum / canCnt) : 12.0;

    return S;
  }

  // Вспомогательная функция точной идентификации модели сухостоя/мертвого дерева
  function isTreeSnag(tree, idx) {
    if (!tree) return false;
    const s = (tree.eco && tree.eco.seasons) || 'all';
    if (s === 'winter_only') return true;
    const name = (tree.name || '').toLowerCase();
    if (name.includes('сухостой') || name.includes('голое') || name.includes('мертв') ||
        name.includes('dead') || name.includes('snag') || name.includes('коряг')) {
      return true;
    }
    const replaceDefault = (localStorage.getItem('wm_tree_replace_default') === 'true');
    if (!replaceDefault && (idx === 8 || idx === 9)) return true;
    return false;
  }

  function placeTrees(S, budget, heightMode, density) {
    const { Nx, Ny, W, H, cls, can } = S;
    const catalog = getActiveTreeCatalog();
    const TOTAL_TYPES = catalog.length;

    // ОПРЕДЕЛЯЕМ ТЕКУЩИЙ ЗУМ
    const curZoom = (S.area && S.area.zoom != null) 
      ? S.area.zoom 
      : (WM.map && WM.map.getZoom ? Math.round(WM.map.getZoom()) : 15);

    // НА ЗУМЕ <= 12 ИЛИ МАКРО-ОБЗОРЕ ДЕРЕВЬЯ НЕ СОЗДАЮТСЯ
    if ((S.area && S.area.isMacro) || curZoom <= 12) {
      const emptyArr = [];
      for (let i = 0; i < TOTAL_TYPES; i++) emptyArr.push(new Float32Array(0));
      return { arr: emptyArr, cnt: new Int32Array(TOTAL_TYPES), spacing: 9999, total: 0 };
    }

    const cap = Math.max(100, budget | 0);
    const mode = heightMode || 'realistic';
    const rnd = mulberry32(hashStr(S.area.key) ^ 0x9e3779b9);

    const span = Math.max(W, H);
    const sceneScaleFactor = clamp(Math.sqrt(span / 1000.0), 0.55, 4.8);
    const cellM = S.area.cellM;

    const arr = [];
    const cnt = new Int32Array(TOTAL_TYPES);
    for (let i = 0; i < TOTAL_TYPES; i++) arr.push(new Float32Array(4096 * 8));
    let total = 0;

    const isWinter = !!(S.isWinter || (S.season && S.season.warmth < -0.35));

    const coniferDryIndices = [];
    const deciduousDryIndices = [];
    const snagIndices = [];

    // Классификация каталога
    catalog.forEach((tree, idx) => {
      if (tree.disabled) return;
      if (isTreeSnag(tree, idx)) {
        snagIndices.push(idx);
        if (tree.eco && tree.eco.kind === 'conifer') coniferDryIndices.push(idx);
        else deciduousDryIndices.push(idx);
      }
    });

    // Взаимный fallback: если нет хвойного сухостоя — берём лиственный (и наоборот), чтобы списки не были пустыми
    if (!coniferDryIndices.length && deciduousDryIndices.length) {
      coniferDryIndices.push(...deciduousDryIndices);
    }
    if (!deciduousDryIndices.length && coniferDryIndices.length) {
      deciduousDryIndices.push(...coniferDryIndices);
    }
    if (!snagIndices.length && (coniferDryIndices.length || deciduousDryIndices.length)) {
      snagIndices.push(...coniferDryIndices, ...deciduousDryIndices);
    }

    const treeP = (c, h) => {
      const L = LC[c];
      if (c === CLS_WATER || c === 35) return 0;
      if (c === 23 || c === 24 || c === 28) return 0.15; // Болота: редкий сухостой
      if (L.group === 2) return (!S.canOk || h >= 2) ? (L.open ? 0.55 : 1) : 0;
      if (L.group === 3) return 0.7;
      if (L.treeP) return h >= 3 ? L.treeP * 3 : 0;
      if (h >= 4) return L.group === 7 ? 0.45 : L.group === 1 ? 0.2 : 0.5;
      return 0;
    };

    const dK = clamp(density != null ? density : 1.0, 0.01, 4.0);
    const nominalS = mode === 'manual' ? Math.max(7.0, 7.0 * sceneScaleFactor * 0.7) : 5.5;
    // При падении густоты базовый шаг сетки растёт (при 0.1 шаг ~17.4 м, при 0.02 шаг ~38.9 м):
    const baseS = nominalS / Math.sqrt(dK);

    const cellA = (W / (Nx - 1)) * (H / (Ny - 1));
    let est = 0;
    const tlM = S.treelineM || 2000;
    for (let i = 0; i < cls.length; i++) {
      const p = treeP(cls[i], can[i] / 4);
      if (!p) continue;
      const ak = 1.0 - smooth(tlM - 350, tlM + 60, S.height[i]);
      const pk = S.rockPeak ? (1.0 - smooth(0.32, 0.80, S.rockPeak[i])) : 1.0;
      est += p * ak * pk * cellA / (baseS * baseS);
    }
    const sp = baseS * Math.max(1, Math.sqrt(est / cap));

    for (let y = sp / 2; y < H; y += sp) {
      for (let x = sp / 2; x < W; x += sp) {
        const jx = clamp(x + (rnd() - 0.5) * sp * 0.85, 0, W);
        const jy = clamp(y + (rnd() - 0.5) * sp * 0.85, 0, H);
        const ci = Math.round(jx / W * (Nx - 1)), cj = Math.round(jy / H * (Ny - 1));
        const k = cj * Nx + ci;

        if (S.roadMask && S.roadMask[k] > 40) continue;

        const c = cls[k], hc = can[k] / 4;
        const p = treeP(c, hc);
        if (!p || rnd() > p) continue;

        const elev = S.height[k];
        const elevRel = clamp((elev - S.hMin) / Math.max(S.relief, 1.0), 0, 1);
        const dx = (S.height[cj * Nx + Math.min(ci + 1, Nx - 1)] - S.height[cj * Nx + Math.max(ci - 1, 0)]) / (2 * (W / (Nx - 1)));
        const dz = (S.height[Math.min(cj + 1, Ny - 1) * Nx + ci] - S.height[Math.max(cj - 1, 0) * Nx + ci]) / (2 * (H / (Ny - 1)));
        const slopeDeg = Math.atan(Math.hypot(dx, dz)) / DEG;

        const L = LC[c];
        const treelineM = S.treelineM || 2000;
        const rockPeak = S.rockPeak ? S.rockPeak[k] : 0;
        const concVal = S.extra ? S.extra[k * 4 + 1] / 255 : 0.5; // >0.5 ложбина, <0.5 гребень

        // Неровная «языковая» граница леса: в кулуарах лес заходит выше, на открытых гребнях ниже
        const forestEdgeNoise = vnoise(jx * 0.005 + 2.1, jy * 0.005 + 6.3) * 0.65
                              + vnoise(jx * 0.016 + 8.4, jy * 0.016 + 1.9) * 0.35;
        const effTreeElev = elev + (0.5 - concVal) * 220.0 + (forestEdgeNoise - 0.5) * 260.0;

        const isRealForest = (L.group === 2);
        const altKeep   = 1.0 - smooth(treelineM - 220, treelineM + 240, effTreeElev);
        // Реальный лес по GLC_FCS30D растёт до 36°..52°; одиночные деревья на лугах редеют с 30°..46°
        const slopeKeep = 1.0 - smooth(isRealForest ? 36.0 : 30.0, isRealForest ? 52.0 : 46.0, slopeDeg);
        const peakKeep  = 1.0 - smooth(isRealForest ? 0.52 : 0.38, 0.92, rockPeak);

        const mtnKeep   = Math.pow(clamp(altKeep * slopeKeep * peakKeep, 0, 1), 0.85);
        if (mtnKeep <= 0.02 || rnd > mtnKeep) continue;


        const r1 = rnd(), r2 = rnd(), r3 = rnd();

        const isNorthFacing = dz > 0.05;
        const isSouthFacing = dz < -0.05;
        const isNearWater = (S.nearWater && S.nearWater[k] === 1);
        const waterDistM = S.distLand ? (S.distLand[k] * cellM) : (isNearWater ? 10.0 : 99999.0);
        const isUrbanZone = (L.group === 7 || c === 30 || (S.roadMask && S.roadMask[k] > 15));

        const calcTreeWeight = (treeIdx) => {
          const tree = catalog[treeIdx];
          if (!tree || tree.disabled) return 0.0;
          const eco = tree.eco || DEFAULT_TREE_ECO;
          const ew = eco.weights || DEFAULT_TREE_ECO.weights;

          let match = 1.0;
          if (L.group === 2) {
            const preferConifer = (L.tree === 1) || (L.tree === 4 && r1 < 0.5);
            if (eco.kind === 'conifer' && !preferConifer) match *= 0.15;
            if (eco.kind === 'deciduous' && preferConifer) match *= 0.15;
          }

          const applyZoneWeight = (inZone, w) => {
            if (!w || w <= 0.001) return;
            if (inZone) match *= (1.0 + w * 12.0);
            else match *= Math.max(0.0001, 1.0 - w * 0.999);
          };

          const targetWaterDist = (ew.waterDistM != null ? ew.waterDistM : 35.0);
          applyZoneWeight(waterDistM <= targetWaterDist, ew.nearWater || 0);

          const targetSlope = (ew.slopeThresholdDeg != null ? ew.slopeThresholdDeg : 28.0);
          applyZoneWeight(slopeDeg >= targetSlope, ew.steepSlope || 0);

          applyZoneWeight((isNorthFacing && slopeDeg > 6.0) || (elevRel < 0.32) || (hc > 16.0), ew.shadeLove || 0);
          applyZoneWeight((isSouthFacing && slopeDeg > 6.0) || (elevRel > 0.65) || (hc < 5.0 && L.group !== 2), ew.sunLove || 0);
          applyZoneWeight(isUrbanZone, ew.urban || 0);

          const alpineZone = clamp(Math.max(1.0 - altKeep, rockPeak), 0, 1);
          if (alpineZone > 0.1) {
            if (eco.kind === 'conifer') match *= (1.0 + alpineZone * 2.5);
            else match *= (1.0 - alpineZone * 0.78);
          }

          return Math.max(0.0, (eco.baseWeight != null ? eco.baseWeight : 1.0) * match);
        };

        let chosenType = -1;
        if (S.forceTreeType != null) {
          if (S.forceTreeType < TOTAL_TYPES && !catalog[S.forceTreeType].disabled) {
            chosenType = S.forceTreeType;
          }
        } else {
          const weights = new Float32Array(TOTAL_TYPES);
          let totalWeight = 0.0;

          // ИСКЛЮЧАЕМ модели сухостоя из общего летнего распределения
          for (let t = 0; t < TOTAL_TYPES; t++) {
            const tree = catalog[t];
            if (tree.disabled || isTreeSnag(tree, t)) continue;
            const w = calcTreeWeight(t);
            weights[t] = w;
            totalWeight += w;
          }

          // Резерв: если в каталоге остались только сухостои
          if (totalWeight <= 0.0001) {
            for (let t = 0; t < TOTAL_TYPES; t++) {
              if (catalog[t].disabled) continue;
              weights[t] = 1.0;
              totalWeight += 1.0;
            }
          }

          if (totalWeight > 0.0001) {
            let pick = rnd() * totalWeight;
            for (let t = 0; t < TOTAL_TYPES; t++) {
              if (weights[t] <= 0.0) continue;
              pick -= weights[t];
              if (pick <= 0) { chosenType = t; break; }
            }
          }
        }

        if (chosenType === -1) continue;

        // 1) ТОЛЬКО СУХОСТОЙ НА БОЛОТАХ
        const isSwamp = (c === 23 || c === 24 || c === 28);
        if (isSwamp) {
          if (snagIndices.length) {
            chosenType = snagIndices[Math.floor(rnd() * snagIndices.length)];
          } else {
            continue;
          }
        }

        const baseDef = catalog[chosenType];
        const sMode = (baseDef.eco && baseDef.eco.seasons) || 'all';
        const isConifer = (baseDef.eco && baseDef.eco.kind === 'conifer');
        const deciduousWinter = !!(baseDef.eco && baseDef.eco.deciduousWinter);

        // Определяем текущий сезон
        const curSeasonId = S.curSeasonId || (S.season && S.season.warmth < -0.35 ? 'winter' : 
                            (S.season && S.season.aut > 0.7 ? 'late_autumn' : 
                            (S.season && S.season.leaf < 0.35 ? 'early_spring' : 'summer')));

        const isEarlySpring = (curSeasonId === 'early_spring');
        const isLateAutumn  = (curSeasonId === 'late_autumn');

        // Дерево не вегетирует (требует сухостоя):
        // 1) Зимой — если sMode !== 'all'
        // 2) Ранней весной и поздней осенью — для 'spring_to_autumn' (с 70% вероятностью согласно пресету)
        let needsSnag = false;
        if (isWinter) {
          needsSnag = (sMode !== 'all');
        } else if (isEarlySpring || isLateAutumn) {
          if (sMode === 'spring_to_autumn' || sMode === 'early_spring_to_late_autumn') {
            needsSnag = r2 < 0.75; // 75% деревьев гарантированно заменяются на модель сухостоя
          }
        }

        let finalType = chosenType;
        let dec = 0;

        if (isSwamp) {
          finalType = chosenType;
          dec = 1;
        } else if (needsSnag) {
          // Подмена 3D-моделью сухостоя (зима, ранняя весна, поздняя осень)
          const dryCandidates = isConifer ? coniferDryIndices : deciduousDryIndices;
          if (dryCandidates.length > 0) {
            let sumDryW = 0.0;
            const dryWeights = new Float32Array(dryCandidates.length);
            for (let d = 0; d < dryCandidates.length; d++) {
              const dw = calcTreeWeight(dryCandidates[d]);
              dryWeights[d] = dw;
              sumDryW += dw;
            }
            if (sumDryW > 0.0001) {
              let pickDry = rnd() * sumDryW;
              let bestDry = -1;
              for (let d = 0; d < dryCandidates.length; d++) {
                pickDry -= dryWeights[d];
                if (pickDry <= 0) { bestDry = dryCandidates[d]; break; }
              }
              finalType = bestDry >= 0 ? bestDry : dryCandidates[0];
            } else {
              finalType = dryCandidates[Math.floor(r2 * dryCandidates.length)];
            }
            dec = 1;
          } else {
            // Если моделек сухостоя нет — оставляем дерево, но сбрасываем крону
            finalType = chosenType;
            dec = 1;
          }
        } else {
          // Обычное состояние: для лиственных деревьев флаг dec = 1 включает шейдерное сбрасывание листвы
          finalType = chosenType;
          dec = deciduousWinter ? 1 : 0;
        }

        const eco = catalog[finalType].eco || {};
        const modelH = getModelMaxY(finalType, treeOverrides[finalType] || catalog[finalType]);
        const safeModelH = Math.max(modelH, 0.2);
        let h, R;

        if (isSwamp) {
          dec = 1;
          const baseSwampH = (eco.heightMode === 'fixed' && eco.fixedHeight) ? eco.fixedHeight :
                             (eco.heightMode === 'relative' && eco.modelScale) ? eco.modelScale : 13.5;
          const targetSwampH = clamp(baseSwampH * 0.65, 3.2, 8.5) * (0.8 + 0.35 * r3);
          h = (eco.heightMode === 'fixed' || eco.heightMode === 'relative')
            ? targetSwampH
            : (targetSwampH / safeModelH);
          R = h * (0.65 + 0.25 * r1);
        } else if (eco.heightMode === 'fixed') {
          const baseH = eco.fixedHeight || 0.7;
          h = baseH * (0.9 + 0.2 * r3);
          R = h * (eco.aspectRatio || 1.0);
        } else if (eco.heightMode === 'relative') {
          const modelScale = eco.modelScale || 12.0;
          h = modelScale * (0.9 + 0.2 * r3);
          R = h;
        } else if (mode === 'manual') {
          // Схематичный (адаптивный): реальный размер задаёт сама 3D-модель (1 ед. модели ≈ 8.5 м)
          // Дуб (2.62) ≈ 22 м, Берёза (2.39) ≈ 20 м, Ель (1.47) ≈ 12.5 м, Куст (0.49) ≈ 4.2 м, Пень (0.24) ≈ 2 м
          h = 8.5 * (0.85 + 0.30 * r3);
          R = h * (0.92 + 0.16 * r3);
        } else {
          // По карте высот ('raw' / 'realistic'): верхушка модели при 1x точно равна targetH в метрах
          let targetH;
          if (mode === 'raw') {
            targetH = Math.max(hc, 2.5);
          } else {
            const forestAvg = S.avgH > 4.0 ? S.avgH : 16.0;
            let normH = hc;
            if (L.group === 2) {
              if (normH < 5.0) {
                normH = forestAvg * (0.75 + 0.3 * r3);
              } else {
                normH = Math.min(normH, forestAvg * 1.45 + 4.0);
                normH = lerp(normH, forestAvg, 0.35);
              }
            } else {
              normH = clamp(normH, 3.5, 22.0);
            }
            targetH = normH;
          }
          // Кустарники и пни (modelH < 0.75) не растягиваем до высоты деревьев
          if (safeModelH < 0.75) {
            targetH = Math.min(targetH, safeModelH * 6.0);
          }
          h = targetH / safeModelH;
          R = h * (0.92 + 0.16 * r3);
        }

        let a = arr[finalType];
        if (!a) arr[finalType] = a = new Float32Array(4096 * 8);

        const o = cnt[finalType]++ * 8;
        if (o + 8 > a.length) {
          const g2 = new Float32Array(a.length * 2);
          g2.set(a);
          arr[finalType] = a = g2;
        }

        if (mtnKeep < 0.90) {
          const stunt = lerp(0.28, 1.0, smooth(0.02, 0.90, mtnKeep));
          h *= stunt;
          R *= lerp(0.55, 1.0, smooth(0.02, 0.90, mtnKeep));
        }

        a[o]     = x - W / 2 + (jx - x);
        a[o + 1] = jy - H / 2;
        a[o + 2] = h;
        a[o + 3] = r1;
        a[o + 4] = R;
        a[o + 5] = r3;
        a[o + 6] = dec;
        a[o + 7] = elev;
        total++;
      }
    }

    return { arr, cnt, spacing: sp, total };
  }

  // ===========================================================================
  // АТМОСФЕРНЫЕ ИСТОЧНИКИ: ПЕЧНОЙ ДЫМ (1–3 НА ГОРОД) + ТУМАН, ПАР И СНЕГОВЕЙ
  // kind: 0 = печь, 1 = котельная/завод, 2 = болото, 3 = низины, 4 = горный снеговей, 5 = дождевая дымка
  // ===========================================================================
   function buildAtmosphericSources(buildingFeatures, S, viewOpts, isMobile) {
    if (!S) return null;
    viewOpts = viewOpts || {};
    const showSmoke = viewOpts.smoke !== false;
    const showMist = viewOpts.mist !== false;
    if (!showSmoke && !showMist) return null;

    const hs = viewOpts.bldHeightScale || 1.0;
    const halfW = S.W * 0.5, halfH = S.H * 0.5;
    const out = [];

    const getH = (wx, wz) => {
      const u = clamp(wx / S.W + 0.5, 0, 1), v = clamp(wz / S.H + 0.5, 0, 1);
      const gx = u * (S.Nx - 1), gy = v * (S.Ny - 1);
      const x0 = Math.min(Math.floor(gx), S.Nx - 2), y0 = Math.min(Math.floor(gy), S.Ny - 2);
      const fx = gx - x0, fy = gy - y0, k = y0 * S.Nx + x0;
      const h = (S.height[k] * (1 - fx) + S.height[k + 1] * fx) * (1 - fy) +
                (S.height[k + S.Nx] * (1 - fx) + S.height[k + S.Nx + 1] * fx) * fy;
      return (h - S.hMin) * (S.zEff || 1.0);
    };

    // 1. ГОРОДСКОЙ ДЫМ (ТРУБЫ ДОМОВ)
    if (showSmoke && buildingFeatures && buildingFeatures.length) {
      const allBld = [];
      buildingFeatures.forEach((feat, fIdx) => {
        const props = feat.props || {};
        feat.geom.forEach(ring => {
          const len = ring.length;
          if (len < 6) return;
          let cx = 0, cz = 0, a2 = 0;
          const pts = (len / 2) - 1;
          for (let i = 0; i < len - 2; i += 2) {
            cx += ring[i]; cz += ring[i + 1];
            a2 += ring[i] * ring[i + 3] - ring[i + 2] * ring[i + 1];
          }
          cx /= pts; cz /= pts;
          const area = Math.abs(a2) * 0.5;
          if (area < 25.0 || Math.abs(cx) > halfW - 20 || Math.abs(cz) > halfH - 20) return;

          const hVal = Math.sin(cx * 12.9898 + cz * 78.233 + fIdx) * 43758.5453;
          const rnd = hVal - Math.floor(hVal);
          let levels = parseFloat(props['building:levels']);
          if (!levels || isNaN(levels)) levels = area < 180 ? (1.0 + rnd * 1.5) : (area < 600 ? (2.5 + rnd * 2.5) : (4.0 + rnd * 6.0));
          const bldH = levels * 3.3 * hs;
          const gabled = area < 550 && levels <= 3.5;
          const roofPitch = gabled ? Math.min(5.0, 2.2 + Math.sqrt(area) * 0.16) * hs : 0.0;
          const topY = getH(cx, cz) + bldH + roofPitch + (gabled ? 0.6 : 1.8);

          allBld.push({ x: cx, y: topY, z: cz, area, rnd, levels });
        });
      });

      const clusterRadius = clamp(Math.max(S.W, S.H) / 12, 450, 950);
      const clusters = [];

      allBld.forEach(b => {
        let bestCl = null, bestD = clusterRadius;
        for (const cl of clusters) {
          const d = Math.hypot(b.x - cl.cx, b.z - cl.cz);
          if (d < bestD) { bestD = d; bestCl = cl; }
        }
        if (bestCl) {
          bestCl.blds.push(b);
          bestCl.cx = (bestCl.cx * (bestCl.blds.length - 1) + b.x) / bestCl.blds.length;
          bestCl.cz = (bestCl.cz * (bestCl.blds.length - 1) + b.z) / bestCl.blds.length;
        } else {
          clusters.push({ cx: b.x, cz: b.z, blds: [b] });
        }
      });

      const pickedChimneys = [];
      const smCityOpt = (viewOpts.smokeMist && viewOpts.smokeMist.city) || {};
      const MAX_TOTAL_CHIMNEYS = smCityOpt.count != null ? smCityOpt.count : (isMobile ? 6 : 14);

      clusters.sort((a, b) => b.blds.length - a.blds.length);

      for (const cl of clusters) {
        if (pickedChimneys.length >= MAX_TOTAL_CHIMNEYS) break;
        const quota = cl.blds.length < 15 ? 1 : (cl.blds.length < 60 ? 2 : 3);
        const sorted = cl.blds.slice().sort((a, b) => (b.area + b.levels * 50) - (a.area + a.levels * 50));

        let added = 0;
        for (const b of sorted) {
          if (added >= quota) break;
          const tooClose = pickedChimneys.some(p => Math.hypot(p.x - b.x, p.z - b.z) < 320);
          if (!tooClose) {
            pickedChimneys.push(b);
            added++;
          }
        }
      }

      pickedChimneys.forEach((q, i) => {
        const industrial = q.area > 650 && q.levels > 3.0;
        const seed = (Math.abs(Math.sin(q.x * 0.131 + q.z * 0.173)) * 1000) % 1;
        const size = industrial ? 1.4 : (0.8 + 0.35 * q.rnd);
        out.push(q.x, q.y, q.z, seed, size, 0.85 + 0.25 * q.rnd, i < 2 ? 1 : 0, industrial ? 1 : 0);
      });
    }

    // 2. ДЫМКА (БОЛОТА, ЗОРИ, НОЧЬ, ПОГОДА)
    if (showMist) {
      const { Nx, Ny, cls, height, extra, hMin, relief } = S;
      const rndGen = mulberry32(hashStr(S.area.key) ^ 0x5a17e);
      const span = Math.max(S.W, S.H);
      const zEff = S.zEff || 1.0;

      // А. БОЛОТА (kind = 2)
      const swampCandidates = [];
      for (let j = 4; j < Ny - 4; j += 3) {
        for (let i = 4; i < Nx - 4; i += 3) {
          const k = j * Nx + i;
          const c = cls[k];
          if (c === 23 || c === 24 || c === 28) {
            const wx = (i / (Nx - 1) - 0.5) * S.W;
            const wz = (j / (Ny - 1) - 0.5) * S.H;
            swampCandidates.push({ x: wx, z: wz, y: (height[k] - hMin) * zEff });
          }
        }
      }
      const maxSwampMists = clamp(Math.round(swampCandidates.length / 5), 0, isMobile ? 8 : 16);
      for (let s = 0; s < maxSwampMists; s++) {
        const idx = Math.floor(rndGen() * swampCandidates.length);
        const p = swampCandidates.splice(idx, 1)[0];
        if (!p) break;
        const seed = rndGen();
        const size = clamp(span * 0.0035, 1.8, 3.8);
        out.push(p.x, p.y + 0.4, p.z, seed, size, 0.95, 0.0, 2.0); // kind = 2 (болото)
      }

      // Б. НИЗИНЫ (kind = 3: утренний и вечерний туман)
      const lowlandCandidates = [];
      for (let j = 5; j < Ny - 5; j += 4) {
        for (let i = 5; i < Nx - 5; i += 4) {
          const k = j * Nx + i;
          const conc = extra[k * 4 + 1];
          const hRel = (height[k] - hMin) / Math.max(relief, 1.0);
          if (conc > 155 && hRel < 0.35 && cls[k] !== CLS_WATER) {
            const wx = (i / (Nx - 1) - 0.5) * S.W;
            const wz = (j / (Ny - 1) - 0.5) * S.H;
            lowlandCandidates.push({ x: wx, z: wz, y: (height[k] - hMin) * zEff });
          }
        }
      }
      const maxLowlands = clamp(Math.round(lowlandCandidates.length / 6), 0, isMobile ? 6 : 14);
      for (let s = 0; s < maxLowlands; s++) {
        const idx = Math.floor(rndGen() * lowlandCandidates.length);
        const p = lowlandCandidates.splice(idx, 1)[0];
        if (!p) break;
        const seed = rndGen();
        const size = clamp(span * 0.004, 2.0, 4.2);
        out.push(p.x, p.y + 0.5, p.z, seed, size, 0.85, 0.0, 3.0); // kind = 3 (низины)
      }

      // В. НОЧНАЯ ДЫМКА (kind = 4: стелющийся холодный туман в низинах и долинах ночью)
      const nightCandidates = [];
      for (let j = 4; j < Ny - 4; j += 4) {
        for (let i = 4; i < Nx - 4; i += 4) {
          const k = j * Nx + i;
          const hRel = (height[k] - hMin) / Math.max(relief, 1.0);
          if (hRel < 0.45 && cls[k] !== CLS_WATER) {
            const wx = (i / (Nx - 1) - 0.5) * S.W;
            const wz = (j / (Ny - 1) - 0.5) * S.H;
            nightCandidates.push({ x: wx, z: wz, y: (height[k] - hMin) * zEff });
          }
        }
      }
      const maxNightMists = clamp(Math.round(nightCandidates.length / 5), 0, isMobile ? 6 : 14);
      for (let s = 0; s < maxNightMists; s++) {
        const idx = Math.floor(rndGen() * nightCandidates.length);
        const p = nightCandidates.splice(idx, 1)[0];
        if (!p) break;
        const seed = rndGen();
        const size = clamp(span * 0.0038, 2.0, 4.2);
        out.push(p.x, p.y + 0.35, p.z, seed, size, 0.90, 0.0, 4.0); // kind = 4 (ночная дымка)
      }

      // Г. ПОГОДНАЯ ДЫМКА (kind = 5: приземная влажная дымка при дожде и тумане)
      const hazeCount = isMobile ? 8 : 16;
      for (let s = 0; s < hazeCount; s++) {
        const rx = (rndGen() - 0.5) * S.W * 0.9;
        const rz = (rndGen() - 0.5) * S.H * 0.9;
        const hy = getH(rx, rz);
        const seed = rndGen();
        const size = clamp(span * 0.003, 1.6, 3.5);
        out.push(rx, hy + 0.6, rz, seed, size, 0.7, 0.0, 5.0); // kind = 5 (погодная дымка)
      }
    }

    return out.length ? { data: new Float32Array(out), count: out.length / 8 } : null;
  }

  // Тайлящаяся fBm-текстура шума (4 канала) — вместо дорогого процедурного шума в фрагментном шейдере
  function makeSmokeNoiseData(N) {
    const data = new Uint8Array(N * N * 4);
    const OCT = [4, 8, 16, 32], AMP = [0.5, 0.27, 0.15, 0.08];
    for (let ch = 0; ch < 4; ch++) {
      let s = (0x9E3779B1 * (ch + 1)) >>> 0;
      const lats = OCT.map(P => {
        const a = new Float32Array(P * P);
        for (let i = 0; i < a.length; i++) { s = (Math.imul(s, 1664525) + 1013904223) >>> 0; a[i] = s / 4294967296; }
        return a;
      });
      for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) {
        let v = 0;
        for (let o = 0; o < 4; o++) {
          const P = OCT[o], L = lats[o];
          const fx = x / N * P, fy = y / N * P;
          const xi = Math.floor(fx), yi = Math.floor(fy), tx = fx - xi, ty = fy - yi;
          const sx = tx * tx * (3 - 2 * tx), sy = ty * ty * (3 - 2 * ty);
          const x1 = (xi + 1) % P, y1 = (yi + 1) % P;
          v += AMP[o] * lerp(lerp(L[yi * P + xi], L[yi * P + x1], sx), lerp(L[y1 * P + xi], L[y1 * P + x1], sx), sy);
        }
        data[(y * N + x) * 4 + ch] = Math.round(clamp((v - 0.5) * 1.6 + 0.5, 0, 1) * 255);
      }
    }
    return data;
  }

  function buildBuildingsMesh(buildingFeatures, area, S, heightScale = 1.0) {
    if (!buildingFeatures || !buildingFeatures.length) return null;
    const pos = [], nrm = [], roof = [], meta = [];      // <-- добавили meta

    const getH = (wx, wz) => {
      const u = clamp(wx / S.W + 0.5, 0, 1), v = clamp(wz / S.H + 0.5, 0, 1);
      const gx = u * (S.Nx - 1), gy = v * (S.Ny - 1);
      const x0 = Math.min(Math.floor(gx), S.Nx - 2), y0 = Math.min(Math.floor(gy), S.Ny - 2);
      const fx = gx - x0, fy = gy - y0;
      const k = y0 * S.Nx + x0;
      const h = (S.height[k] * (1 - fx) + S.height[k + 1] * fx) * (1 - fy) +
                (S.height[k + S.Nx] * (1 - fx) + S.height[k + S.Nx + 1] * fx) * fy;
      return (h - S.hMin) * (S.zEff || 1.0);
    };

    const halfW = S.W * 0.5 + 5.0;
    const halfH = S.H * 0.5 + 5.0;

    const minAreaThreshold = S.W > 10000 ? 40.0 : 0.0;

    buildingFeatures.forEach((feat, fIdx) => {
      feat.geom.forEach(ring => {
        const len = ring.length;
        if (len < 6) return;

        const beforePos = pos.length;

        // Расчёт площади и центроида
        let cx = 0, cz = 0, pts = (len / 2) - 1;
        let area2 = 0;
        let longestEdgeLen = 0;
        let ridgeDirX = 1, ridgeDirZ = 0;

        for (let i = 0; i < len - 2; i += 2) {
          const x1 = ring[i], z1 = ring[i + 1];
          const x2 = ring[i + 2], z2 = ring[i + 3];
          cx += x1; cz += z1;
          area2 += x1 * z2 - x2 * z1;

          const edx = x2 - x1, edz = z2 - z1;
          const elen = Math.hypot(edx, edz);
          if (elen > longestEdgeLen) {
            longestEdgeLen = elen;
            ridgeDirX = edx / elen;
            ridgeDirZ = edz / elen;
          }
        }
        cx /= pts; cz /= pts;
        const bldArea = Math.abs(area2) * 0.5;

        // Отсекаем микропостройки при широком охвате
        if (bldArea < minAreaThreshold) return;


        // Псевдослучайный хэш
        const hVal = Math.sin(cx * 12.9898 + cz * 78.233 + fIdx) * 43758.5453;
        const rnd = hVal - Math.floor(hVal);

        // Высота стен
        let levels = parseFloat(feat.props['building:levels']);
        if (!levels || isNaN(levels)) {
          levels = bldArea < 180 ? (1.0 + rnd * 1.5) : (bldArea < 600 ? (2.5 + rnd * 2.5) : (4.0 + rnd * 6.0));
        }
        const bldH = levels * 3.3 * heightScale;

        // Частный сектор и невысокие здания получают классическую двускатную крышу
        const isGabled = bldArea < 550 && levels <= 3.5;
        const roofPitch = isGabled ? Math.min(5.0, 2.2 + Math.sqrt(bldArea) * 0.16) * heightScale : 0.0;

        // 1. СТЕНЫ ФАСАДОВ
        for (let i = 0; i < len - 2; i += 2) {
          const x1 = ring[i],     z1 = ring[i + 1];
          const x2 = ring[i + 2], z2 = ring[i + 3];
          const h1 = getH(x1, z1), h2 = getH(x2, z2);

          const dx = x2 - x1, dz = z2 - z1;
          const dLen = Math.hypot(dx, dz) || 1.0;
          const nx = dz / dLen, nz = -dx / dLen;

          pos.push(
            x1, h1, z1,          x2, h2, z2,          x1, h1 + bldH, z1,
            x1, h1 + bldH, z1,   x2, h2, z2,          x2, h2 + bldH, z2
          );
          for (let k = 0; k < 6; k++) {
            nrm.push(nx, 0.0, nz);
            roof.push(0.0);
          }
        }

        // 2. КРЫША: ДВУСКАТНАЯ «БУКВА Л» ИЛИ ПЛОСКАЯ
        if (isGabled) {
          // Высота конька над уровнем земли
          const ridgeBaseH = getH(cx, cz) + bldH + roofPitch;

          // Для каждого сегмента определяем: это продольный скат (крыша) или торцевой фронтон (вертикальная стена)
          for (let i = 0; i < len - 2; i += 2) {
            const x1 = ring[i],     z1 = ring[i + 1];
            const x2 = ring[i + 2], z2 = ring[i + 3];
            const hw1 = getH(x1, z1) + bldH;
            const hw2 = getH(x2, z2) + bldH;

            const edx = x2 - x1, edz = z2 - z1;
            const elen = Math.hypot(edx, edz) || 1.0;

            // Вычисляем косинус угла между стеной и коньком
            const cosRidge = Math.abs((edx * ridgeDirX + edz * ridgeDirZ) / elen);

            // Проекция точек стены на осевую линию конька
            const p1Proj = (x1 - cx) * ridgeDirX + (z1 - cz) * ridgeDirZ;
            const p2Proj = (x2 - cx) * ridgeDirX + (z2 - cz) * ridgeDirZ;

            const r1x = cx + ridgeDirX * p1Proj, r1z = cz + ridgeDirZ * p1Proj;
            const r2x = cx + ridgeDirX * p2Proj, r2z = cz + ridgeDirZ * p2Proj;

            if (cosRidge > 0.45) {
              // ПРОДОЛЬНЫЙ СКАТ (наклонная грань скатной крыши)
              // Векторы плоскости ската для расчета точной нормали
              const ux = x2 - x1, uy = hw2 - hw1, uz = z2 - z1;
              const vx = r1x - x1, vy = ridgeBaseH - hw1, vz = r1z - z1;
              let snx = uy * vz - uz * vy;
              let sny = uz * vx - ux * vz;
              let snz = ux * vy - uy * vx;
              const snl = Math.hypot(snx, sny, snz) || 1.0;
              snx /= snl; sny = Math.abs(sny / snl); snz /= snl;

              pos.push(
                x1, hw1, z1,     x2, hw2, z2,     r1x, ridgeBaseH, r1z,
                r1x, ridgeBaseH, r1z, x2, hw2, z2, r2x, ridgeBaseH, r2z
              );
              for (let k = 0; k < 6; k++) {
                nrm.push(snx, sny, snz);
                roof.push(1.0); // Скаты рендерятся черепицей/шифером
              }
            } else {
              // ТОРЦЕВОЙ ФРОНТОН («щипец» фасада треугольником)
              // На коньке берется ближайшая центральная вершина треугольника
              const midProj = (p1Proj + p2Proj) * 0.5;
              const rmidX = cx + ridgeDirX * midProj;
              const rmidZ = cz + ridgeDirZ * midProj;

              // Нормаль фронтона вертикальна и параллельна торцу стены
              const fnx = edz / elen, fnz = -edx / elen;

              pos.push(
                x1, hw1, z1,
                x2, hw2, z2,
                rmidX, ridgeBaseH, rmidZ
              );
              for (let k = 0; k < 3; k++) {
                nrm.push(fnx, 0.0, fnz);
                roof.push(0.0); // Фронтон рендерится как продолжение стены (кирпич/фасад)
              }
            }
          }
        } else {
          // ДЛЯ КРУПНЫХ / ВЫСОКИХ ЗДАНИЙ — ПЛОСКАЯ КРЫША С ПАРАПЕТОМ
          const flatH = getH(cx, cz) + bldH;
          for (let i = 0; i < len - 2; i += 2) {
            pos.push(
              cx, flatH, cz,
              ring[i], getH(ring[i], ring[i + 1]) + bldH, ring[i + 1],
              ring[i + 2], getH(ring[i + 2], ring[i + 3]) + bldH, ring[i + 3]
            );
            for (let k = 0; k < 3; k++) {
              nrm.push(0.0, 1.0, 0.0);
              roof.push(1.0);
            }
          }
        }
      // === ВСТАВИТЬ ПОСЛЕ ЗАВЕРШЕНИЯ ВСЕХ pos.push ДЛЯ ЭТОГО ЗДАНИЯ ===
        const footprintW = Math.max(3.0, Math.sqrt(bldArea));
        const areaClass  = bldArea < 180 ? 0.0 : (bldArea < 600 ? 1.0 : 2.0);
        const newVerts   = (pos.length - beforePos) / 3;
        for (let v = 0; v < newVerts; v++) {
          meta.push(footprintW, rnd, areaClass, levels);
        }
      });
    });

    return {
      vertexData: new Float32Array(pos),
      normalData: new Float32Array(nrm),
      roofData:   new Float32Array(roof),
      metaData:   new Float32Array(meta),     // <-- новое
      count: pos.length / 3
    };
  }
  // ===========================================================================
  // 9. ПОЧВЕННЫЕ ГОРИЗОНТЫ
  // ===========================================================================
  const HORIZONS = [
    { name: 'Подстилка / гумусовый (A0–A1)', depth: '0–5 см' },
    { name: 'Гумусово-элювиальный (A/E)', depth: '5–15 см' },
    { name: 'Иллювиальный (B)', depth: '15–30 см' },
    { name: 'Переходный (BC)', depth: '30–60 см' },
    { name: 'Материнская порода (C)', depth: '> 60 см' }
  ];
  function horizonColor(h, idx, ctx) {
    const sand = h.sand, clay = h.clay, silt = h.silt, soc = h.soc, ph = h.ph;
    
    // Эталонная генетическая палитра горизонтов (A0, A2/E, B, BC, C)
    const BASE_HORIZONS = [
      [0.17, 0.11, 0.07], // 0: A0/A1 — богатый органикой тёмно-бурый гумус
      [0.46, 0.40, 0.33], // 1: A/E   — оподзоленный / выщелоченный светло-серый элювий
      [0.56, 0.30, 0.14], // 2: B     — иллювиальный горизонт вмывания (глинисто-ржавый/бурый)
      [0.68, 0.52, 0.32], // 3: BC    — переходный суглинисто-песчаный охристый слой
      [0.42, 0.41, 0.40]  // 4: C     — материнская горная порода (серо-каменная)
    ];

    let c = BASE_HORIZONS[idx].slice();

    // Модуляция гранулометрическим составом
    const sc = [0.78, 0.66, 0.46]; // Песок (светло-жёлтый)
    const cc = [0.55, 0.28, 0.16]; // Глина (красно-коричневая)
    if (sand > 35) c = mix3(c, sc, (sand - 35) / 65 * 0.45);
    if (clay > 20) c = mix3(c, cc, (clay - 20) / 80 * 0.50);

    // Влияние кислотности: при кислой почве подзолистый элювий светлеет
    if (idx === 1 && ph < 5.5) c = mix3(c, [0.65, 0.63, 0.60], clamp((5.5 - ph) / 1.5, 0, 1) * 0.5);
    if (ph > 7.5) c = mix3(c, [0.75, 0.72, 0.58], clamp((ph - 7.5) / 1.5, 0, 1) * 0.3);

    // Гумусовое затемнение
    const om = clamp(soc / (idx === 0 ? 50 : 35), 0, 1);
    c = mix3(c, [0.10, 0.07, 0.04], Math.pow(om, 0.7) * (idx === 0 ? 0.85 : 0.65));

    if (ctx.wet > 0.6 && idx >= 2) c = mix3(c, [0.42, 0.48, 0.48], (ctx.wet - 0.6) * 1.2);
    return c;
  }
  function buildSoilLayers(soil, agro, wx, wetAvg) {
    if (!soil || !soil.profile) return null;
    const P = soil.profile;
    const g = (i, k, d) => { for (const j of [i, i - 1, i + 1, 0]) if (P[j] && P[j][k] != null) return P[j][k]; return d; };
    const hs = [];
    for (let i = 0; i < 4; i++) {
      const sand = g(i, 'sand', 40), clay = g(i, 'clay', 20);
      let rawPh = g(i, 'phh2o', 6.2);
      if (rawPh > 25) rawPh /= 10.0; // Корректировка формата SoilGrids (65 -> 6.5)
      let rawSoc = g(i, 'soc', 25);
      if (rawSoc > 200) rawSoc /= 10.0; // dg/kg -> g/kg
      hs.push({
        sand, clay,
        silt: g(i, 'silt', Math.max(0, 100 - sand - clay)),
        soc: clamp(rawSoc, 2, 90),
        ph: clamp(rawPh, 4.0, 8.8),
        cfvo: g(i, 'cfvo', 4), bdod: g(i, 'bdod', 1.2), cec: g(i, 'cec', 15), n: g(i, 'nitrogen', 2)
      });
    }
    const d4 = hs[3];
    // 5-й слой — материнская горная порода (бедрок): меньше гумуса, больше минерализации
    hs.push({
      sand: d4.sand, clay: clamp(d4.clay + 5, 0, 80), silt: d4.silt,
      soc: Math.max(1.0, d4.soc * 0.15),
      ph: clamp(d4.ph + 0.4, 4.5, 9.0),
      cfvo: clamp(d4.cfvo * 2.2 + 15, 10, 80),
      bdod: d4.bdod + 0.2, cec: d4.cec, n: 0.2
    });
    const m0 = wx && wx.soilM0 != null ? wx.soilM0 : (agro ? agro.m0 : null);
    const m39 = agro ? agro.m39 : (wx && wx.soilM3 != null ? wx.soilM3 : m0);
    const t0 = wx && wx.soilT0 != null ? wx.soilT0 : (agro ? agro.soilT0 : null);
    const t6 = wx && wx.soilT6 != null ? wx.soilT6 : (agro ? agro.soilT6 : t0);
    const t18 = agro ? agro.soilT18 : t6;
    const known = { moist: m0 != null, temp: t0 != null };
    const mm = [m0, m0 != null && m39 != null ? (m0 + m39) / 2 : m39, m39, m39 != null ? m39 * 1.05 : null, m39 != null ? m39 * 1.1 : null];
    const tt = t0 == null ? [null, null, null, null, null] :
      [lerp(t0, t6, 0.4), lerp(t6, t18 ?? t6, 0.33), t18 ?? t6, (t18 ?? t6) + ((t18 ?? t6) - t6) * 0.35, (t18 ?? t6) + ((t18 ?? t6) - t6) * 0.6];
    const w = [5, 10, 15, 30].map(v => Math.pow(v, 0.6)), ws = w.reduce((a, b) => a + b, 0);
    const bnd = []; let acc = 0;
    for (let i = 0; i < 4; i++) { acc += w[i]; bnd.push(0.62 * acc / ws); }
    const out = { col: [], P: [], V: [], B: bnd, info: [], known, frozen: t0 != null && t0 <= 0 };
    hs.forEach((h, i) => {
      const col = horizonColor(h, i, { wet: wetAvg });
      const mo = mm[i] == null ? 0.4 : clamp(mm[i] / 0.5, 0, 1), te = tt[i] == null ? 8 : tt[i];
      out.col.push(col);
      out.P.push([h.sand / 100, h.clay / 100, clamp(h.soc / 100, 0, 1), clamp(h.cfvo / 40, 0, 1)]);
      out.V.push([mo, te, h.soc, h.ph]);
      out.info.push({
        name: HORIZONS[i].name, depth: HORIZONS[i].depth,
        css: '#' + col.map(v => pad2(Math.round(clamp(v, 0, 1) * 255).toString(16))).join(''),
        txt: `песок ${Math.round(h.sand)}% · глина ${Math.round(h.clay)}% · pH ${h.ph.toFixed(1)} · C ${Math.round(h.soc)} г/кг` + (i < 4 && h.cfvo > 8 ? ` · камни ${Math.round(h.cfvo)}%` : '') + (mm[i] != null ? ` · влажн. ${Math.round(mm[i] * 100)}%` : '') + (tt[i] != null ? ` · ${tt[i].toFixed(1)}°` : '')
      });
    });
    return out;
  }

  // ===========================================================================
  // 10. ОСВЕЩЕНИЕ / ОКРУЖЕНИЕ
  // ===========================================================================
  const SKY_STOPS_DUSK = [
    [-90, [0.010, 0.015, 0.035], [0.015, 0.025, 0.055]],
    [-18, [0.012, 0.020, 0.050], [0.020, 0.035, 0.080]],
    [-12, [0.040, 0.070, 0.220], [0.100, 0.160, 0.380]],
    [-8,  [0.060, 0.130, 0.380], [0.160, 0.260, 0.520]],
    [-4,  [0.090, 0.190, 0.480], [0.240, 0.340, 0.580]],
    [0,   [0.130, 0.260, 0.580], [0.380, 0.410, 0.560]],
    [5,   [0.190, 0.370, 0.740], [0.580, 0.620, 0.760]],
    [15,  [0.250, 0.470, 0.860], [0.750, 0.830, 0.940]],
    [90,  [0.180, 0.420, 0.860], [0.700, 0.820, 0.950]]
  ];

  const SKY_STOPS_DAWN = [
    [-90, [0.010, 0.015, 0.035], [0.015, 0.025, 0.055]],
    [-22, [0.012, 0.022, 0.055], [0.022, 0.038, 0.095]],
    [-16, [0.024, 0.048, 0.140], [0.075, 0.130, 0.280]],
    [-11, [0.050, 0.105, 0.280], [0.200, 0.290, 0.480]],
    [-6,  [0.090, 0.190, 0.440], [0.320, 0.400, 0.560]],
    [-2,  [0.110, 0.240, 0.540], [0.380, 0.450, 0.590]],
    [0,   [0.150, 0.320, 0.640], [0.430, 0.490, 0.620]],
    [5,   [0.200, 0.410, 0.780], [0.580, 0.660, 0.800]],
    [15,  [0.240, 0.480, 0.860], [0.740, 0.850, 0.950]],
    [90,  [0.180, 0.420, 0.860], [0.700, 0.820, 0.950]]
  ];

  function skyAt(alt, isMorning) {
    const stops = isMorning ? SKY_STOPS_DAWN : SKY_STOPS_DUSK;
    for (let i = 1; i < stops.length; i++) {
      if (alt <= stops[i][0]) {
        const a = stops[i - 1], b = stops[i], t = (alt - a[0]) / (b[0] - a[0]);
        return { top: mix3(a[1], b[1], t), hor: mix3(a[2], b[2], t) };
      }
    }
    const l = stops[stops.length - 1]; return { top: l[1], hor: l[2] };
  }
  const normv = v => { const l = Math.hypot(v[0], v[1], v[2]) || 1; return [v[0] / l, v[1] / l, v[2] / l]; };

  function lightColAt(altD, isMorning) {
    const noon   = lin3([1.00, 0.97, 0.92]);
    const golden = lin3([1.00, 0.84, 0.58]);
    let c;
    if (isMorning) {
      // РАССВЕТ: первые лучи на пиках розовато-алые -> затем оранжевые -> золотые
      c = mix3(lin3([1.00, 0.16, 0.06]), lin3([1.00, 0.44, 0.12]), smooth(-5.2, -0.5, altD));
      c = mix3(c, lin3([1.00, 0.68, 0.24]), smooth(-0.5, 3.0, altD));
      c = mix3(c, golden, smooth(3.0, 9.0, altD));
      return mix3(c, noon, smooth(9.0, 26.0, altD));
    }
    // ЗАКАТ: раньше уходит от дневного белого в золото (34°->15°), насыщенный оранжевый (15°->6.5°) и багрянец
    const warmGold = lin3([1.00, 0.72, 0.34]);
    c = mix3(lin3([1.00, 0.08, 0.02]), lin3([1.00, 0.20, 0.04]), smooth(-5.2, 0.0, altD));
    c = mix3(c, lin3([1.00, 0.40, 0.09]), smooth(0.0, 6.5, altD));
    c = mix3(c, warmGold, smooth(6.5, 15.0, altD));
    return mix3(c, noon, smooth(15.0, 34.0, altD));
  }

  function makeDefaultAtmoVecs() {
    return {
      sunDiscTop: [1, 0.5, 0.1], sunDiscSize: 1.0,
      sunDiscMid: [1, 0.3, 0.05], sunDiscBright: 1.0,
      sunDiscBot: [1, 0.15, 0.02], sunDiscCore: 1.0,
      sunHaloCol: [1, 0.4, 0.1], sunHaloInt: 1.0,
      twilightGlowCol: [0.85, 0.3, 0.1], twilightGlowInt: 1.0,
      venusBeltCol: [0.55, 0.44, 0.66], venusBeltInt: 1.0,
      alpenCol: [1, 0.25, 0.05], alpenInt: 1.0,
      skyHorPow: 3.0, atmoOverride: 0.0, sunHazePass: 1.0, preDawnInt: 1.0,
      mistCol: [0.4, 0.55, 0.85], mistColMix: 0.0
    };
  }

  function computeEnv(p) {
    const altD = p.alt / DEG, wx = p.wx;
    const cloud = clamp(wx.cloud, 0, 1);
    const storm = Math.max(wx.rain, wx.snow);
    const isFog = wx.fog > 0.05;
    const sunDir = dirFromAltAz(p.alt, p.az);
    const isMorning = p.hour != null ? (p.hour < 12.0) : (Math.sin(p.az) > 0);

    // Зима: холодное небо после заката ярче и чище
    const winter = clamp(Math.max(wx.snowCover || 0, smooth(3, -8, wx.temp != null ? wx.temp : 10)), 0, 1);

    const nCfg = (WM.nightDev && WM.nightDev.getConfig) ? WM.nightDev.getConfig() : null;
    const twDur = nCfg ? nCfg.twilight.duration : 1.0;
    const twWarm = nCfg ? nCfg.twilight.warmth : 1.0;
    const blueBoost = nCfg ? nCfg.twilight.blueHour : 1.0;
    const wxDark = nCfg ? Math.max(0.01, 1.0 - (nCfg.weather.weatherDarkness != null ? nCfg.weather.weatherDarkness : 0.65)) : 1.0;
    const fogDark = nCfg ? (nCfg.weather.fogDarkness != null ? nCfg.weather.fogDarkness : 0.75) : 0.0;
    const fogFloor = Math.max(0.001, (1.0 - fogDark) * 0.05);

    // Длина сумерек масштабирует высотные границы смены дня и ночи
    const night = 1 - smooth(-15 * twDur, -5 * twDur, altD);
    const blueHour = smooth(-11 * twDur, -5 * twDur, altD) * smooth(0, -3 * twDur, altD) * blueBoost;
    const lowSun = smooth(20 * twDur, 0, altD) * smooth(-10 * twDur, -2 * twDur, altD);

    const sk = skyAt(altD, isMorning);
    let top = lin3(sk.top), hor = lin3(sk.hor);

    if (!isMorning && blueHour > 0.001 && winter > 0.01) {
      const w = winter * blueHour;
      top = mul3(mix3(top, lin3([0.20, 0.38, 0.85]), w * 0.45), 1 + 0.30 * w);
      hor = mix3(hor, lin3([0.62, 0.55, 0.80]), w * 0.35);
    }

    // 🌅 ЗИМНИЙ РАССВЕТ: тёплое оранжевое свечение на снегу и в небе
    const winterDawn = isMorning
      ? winter * smooth(-8, 6, altD) * (1 - smooth(12, 22, altD))
      : 0;
    if (winterDawn > 0.01) {
      // Горизонт уходит в тёплый золотисто-оранжевый (морозный рассвет)
      hor = mix3(hor, lin3([1.00, 0.62, 0.32]), winterDawn * 0.60);
      // Верх неба — мягкий персиковый подмес
      top = mix3(top, lin3([0.85, 0.60, 0.55]), winterDawn * 0.22);
    }

    const coldTint = clamp(wx.coldTint || 0, 0, 1);
    if (coldTint > 0.01) {
      const coldSky = lin3([0.62, 0.76, 0.94]);
      top = mix3(top, coldSky, coldTint * 0.35);
      hor = mix3(hor, coldSky, coldTint * 0.45);
    }
    const overcastFactor = smooth(0.25, 0.90, cloud);
    const gray = clamp(overcastFactor * 0.88 + storm * 0.12 + wx.fog * 0.9, 0, 0.98);
    // Нижний порог 0.42 не даёт сумеркам с дождём/грозой провалиться в черноту
    let stormDark = Math.max(0.42, 1.0 - 0.42 * storm - (wx.thunder > 0 ? 0.18 : 0) - wx.fog * 0.15);
    stormDark *= lerp(1.0, wxDark, night * gray);
    const dull = c => {
      const l = (0.299 * c[0] + 0.587 * c[1] + 0.114 * c[2]);
      return mul3(mix3(c, [l, l * 1.02, l * 1.05], gray), stormDark);
    };
    top = dull(top);
    hor = dull(hor);

    // Мягкий тёплый подтон у облачного горизонта на закате/рассвете (как на рефах 1 и 4)
    if (lowSun > 0.01) {
      const sunsetEmber = isMorning ? lin3([0.62, 0.30, 0.16]) : lin3([0.64, 0.24, 0.11]);
      const emberAmt = lowSun * smooth(-4.5, 2.0, altD) * 0.28 * (1.0 - wx.fog * 0.65);
      hor = mix3(hor, mul3(sunsetEmber, Math.max(stormDark, 0.55)), emberAmt);
    }

    // ---- Прямой свет ----
    const sunBreakthrough = lerp(1.0, 0.45, overcastFactor);
    // Оставляем небольшой просвет в лёгкой мгле, чтобы рельеф/вода не стали плоскими
    const sunCut = sunBreakthrough * Math.max(0.18, 1 - 0.82 * smooth(0.08, 0.75, wx.fog));

    const sunRiseStart = -5.2;
    const goldenPeak = isMorning
      ? smooth(-4.8, 1.5, altD) * (1 - smooth(6.5, 16.0, altD))
      : smooth(-4.8, 1.0, altD) * (1 - smooth(5.0, 15.0, altD));
    const sunBase = isMorning
      ? 3.6 * Math.pow(smooth(sunRiseStart, 9.0, altD), 0.7) + 1.25 * goldenPeak
      : 3.6 * Math.pow(smooth(sunRiseStart, 18.0, altD), 0.95) + 0.45 * goldenPeak;
    const sunInt = sunBase * sunCut;
    let sunCol = lightColAt(altD, isMorning);
    if (winterDawn > 0.01) {
      sunCol = mix3(sunCol, lin3([1.00, 0.42, 0.14]), winterDawn * 0.50);
    }
    // ---- Цвет самого диска ----
    const discRed = clamp(isMorning ? 1 - smooth(-0.8, 5.5, altD) : 1 - smooth(-0.8, 6.8, altD), 0, 1);

    // ---- Луна ----
    const moon = p.moon || { dir: normv([0.3, 0.8, -0.3]), illum: 0.4, alt: 0.5 };

    const moonIntensityMul = nCfg ? nCfg.moon.intensity : 1.0;
    const customMoonCol = nCfg ? lin3(hex3(nCfg.moon.color)) : lin3([0.50, 0.72, 1.00]);
    const skyGlowMul = nCfg ? nCfg.ambient.skyGlow : 1.0;

    const moonInt = ((0.24 + 0.32 * moon.illum) * smooth(-4, 5, moon.alt / DEG) + 0.055) * (1 - 0.75 * cloud) * moonIntensityMul;
    const nightLightColor = customMoonCol;

    const ldir = normv(mix3(sunDir, moon.dir, night));
    const lcol = mix3(sunCol, nightLightColor, night);
    const lint = sunInt * (1 - night) + moonInt * night;

    // ---- Рассеянный свет ----
    const wxNightDarkFactor = lerp(1.0, wxDark, gray);
    const clearSkyFactor = (1.0 - gray * 0.85);

    // ---- 2. Рассеянный свет (Ambient) ----
    const ambS = 0.10 + 0.58 * smooth(-8, 14, altD) + 0.12 * blueHour + 0.09 * smooth(-4, 2, altD) * (1 - smooth(2, 12, altD));
    // top и hor уже содержат stormDark из dull(), повторно умножать не нужно
    let amb = mul3(mix3(top, hor, 0.5), ambS * (0.85 + 0.95 * overcastFactor));

    const morningShadowTint = winterDawn > 0.01
      ? mix3(lin3([0.30, 0.52, 1.00]), lin3([0.92, 0.55, 0.32]), winterDawn)
      : lin3([0.30, 0.52, 1.00]);
    const shadowTint = isMorning ? morningShadowTint : lin3([0.34, 0.26, 0.85]);
    amb = mix3(amb, mul3(shadowTint, ambS * 1.2), lowSun * 0.55 * clearSkyFactor);

    // Ночное свечение неба — гасится ползунком weatherDarkness в тумане
    const nightSkyGlow = nCfg
      ? mul3(lin3(hex3(nCfg.ambient.nightSkyColor)), 0.35 * skyGlowMul * wxNightDarkFactor)
      : mul3(lin3([0.09, 0.14, 0.26]), wxNightDarkFactor);
    for (let i = 0; i < 3; i++) amb[i] += nightSkyGlow[i] * night * (1.0 - cloud * 0.55);

    // ---- 3. Подсветка снизу (Ground / Снег) ----
    let gnd = mul3(lin3([0.35, 0.30, 0.22]), ambS * 1.1 * stormDark);
    gnd = mix3(gnd, mul3(isMorning ? lin3([0.18, 0.26, 0.45]) : lin3([0.20, 0.12, 0.36]), ambS * 1.4),
               lowSun * 0.55 * clearSkyFactor);

    const nightGndGlow = nCfg
      ? mul3(lin3(hex3(nCfg.ambient.nightGroundColor)), 0.25 * skyGlowMul * wxNightDarkFactor)
      : mul3(lin3([0.045, 0.075, 0.15]), wxNightDarkFactor);
    for (let i = 0; i < 3; i++) gnd[i] += nightGndGlow[i] * night * (1.0 - cloud * 0.55);

    // Рассеянный по небу свет Луны (подсвечивает теневые склоны даже когда диск за горой)
    const moonSkyScatter = (0.006 + 0.012 * moon.illum) * smooth(-6, 12, moon.alt / DEG) * night * wxNightDarkFactor;
    amb[0] += moonSkyScatter * 0.65; amb[1] += moonSkyScatter * 0.85; amb[2] += moonSkyScatter * 1.15;
    gnd[0] += moonSkyScatter * 0.35; gnd[1] += moonSkyScatter * 0.45; gnd[2] += moonSkyScatter * 0.65;

    // 🌅 Тёплая подсветка снега снизу на рассвете (видна на ясном восходе, не светит сквозь туман)
    if (winterDawn > 0.01) {
      gnd = mix3(gnd, mul3(lin3([1.00, 0.68, 0.42]), ambS * 0.85), winterDawn * 0.55 * clearSkyFactor);
    }

    // ❄️ Зимой ночью — усиленная синева на снегу (в буран и мглу приглушается wxNightDarkFactor)
    const winterNight = winter * night;
    if (winterNight > 0.01) {
      amb = mix3(amb, mul3(lin3([0.10, 0.22, 0.55]), ambS * 0.9 * wxNightDarkFactor), winterNight * 0.30 * clearSkyFactor);
      gnd = mix3(gnd, mul3(lin3([0.06, 0.16, 0.40]), ambS * 0.7 * wxNightDarkFactor), winterNight * 0.35 * clearSkyFactor);
    }

    // ---- 4. Цвет и плотность тумана (Fog) ----
    const dhScale = clamp(twDur, 0.75, 1.3);
    // Тянем дымку глубже в ночь (с -21°), пик в предрассветные сумерки (-13°..-1°), мягкое рассеивание к +8.5°
    const dawnHaze = isMorning ? smooth(-21 * dhScale, -9 * dhScale, altD) * smooth(8.5, -1.5, altD) : 0;
    const dawnHazeRaw = isMorning ? smooth(-21 * dhScale, -10 * dhScale, altD) * smooth(9.5, -1.0, altD) : 0;

    const wFog  = clamp(wx.fog || 0, 0, 1);
    const wRain = clamp(wx.rain || 0, 0, 1);
    const wSnow = clamp(wx.snow || 0, 0, 1);
    const isFreeze = !!(wx.ice || coldTint > 0.2 || (wx.temp != null && wx.temp < -2));

    // Базовый цвет тумана
     const fogBaseCol = isFog ? mix(lin3([0.75, 0.77, 0.80]), hor, gray) : hor;
    const fogDayScale = 0.22 + 0.78 * smooth(-5.0, 12.0, altD);
    const fogWarmRef = mix3(mul3(lin3([0.68, 0.70, 0.74]), fogDayScale), hor, lowSun * 0.45);
    let fogCol = mix(fogBaseCol, fogWarmRef, wFog * (1.0 - night * 0.8));

    if (night > 0.01) {
      const fogLum = (0.299 * fogCol[0] + 0.587 * fogCol[1] + 0.114 * fogCol[2]);
      const nightDarkTarget = Math.pow(Math.max(0.0, 1.0 - fogDark), 1.8) * lerp(1.0, wxDark, gray);
      const darkMul = lerp(1.0, nightDarkTarget, night);
      const targetFogL = Math.max(0.0001, fogLum * darkMul);
      fogCol = mul3(fogCol, targetFogL / Math.max(fogLum, 1e-4));
    }

    let groundMist = 0;
    let mistWarmHor = 0;
    if (dawnHazeRaw > 0.001) {
      // Оттенки предрассветной дымки под разные режимы погоды
      const dawnClearCol = mix3(lin3([0.28, 0.46, 0.88]), lin3([0.56, 0.72, 0.96]), smooth(-13, 1, altD)); // Ясно (рефы 1, 3)
      const dawnCloudCol = mix3(lin3([0.18, 0.28, 0.56]), lin3([0.34, 0.46, 0.72]), smooth(-13, 2, altD)); // Облачно (реф 2)
      const dawnFogCol = isFreeze
        ? mix3(lin3([0.36, 0.58, 0.88]), lin3([0.58, 0.78, 0.96]), smooth(-13, 2, altD))                  // Ледяной туман
        : mix3(lin3([0.42, 0.58, 0.84]), lin3([0.66, 0.76, 0.92]), smooth(-13, 2, altD));                 // Плотный туман (рефы 1, 4)
      const dawnRainCol  = lin3([0.16, 0.26, 0.48]);                                                       // Дождь / морось
      const dawnSnowCol  = mix3(lin3([0.30, 0.48, 0.86]), lin3([0.56, 0.72, 0.95]), smooth(-13, 2, altD)); // Снег

      let dawnMistCol = mix3(dawnClearCol, dawnCloudCol, overcastFactor * 0.85);
      if (wFog > 0.02)  dawnMistCol = mix3(dawnMistCol, dawnFogCol,  smooth(0.02, 0.45, wFog));
      if (wRain > 0.02) dawnMistCol = mix3(dawnMistCol, dawnRainCol, smooth(0.02, 0.50, wRain) * 0.85);
      if (wSnow > 0.02) dawnMistCol = mix3(dawnMistCol, dawnSnowCol, smooth(0.02, 0.45, wSnow) * 0.85);

      // Снижаем насыщенность утренней синей дымки (~35% к нейтральной яркости)
      const dLum = 0.299 * dawnMistCol[0] + 0.587 * dawnMistCol[1] + 0.114 * dawnMistCol[2];
      dawnMistCol = mix3(dawnMistCol, [dLum, dLum, dLum], 0.35);

      const dawnLum = (0.22 + 0.34 * smooth(-21, -3, altD) + 0.38 * smooth(2, 11, altD)) * (1.0 - 0.35 * storm);
      const dawnFogTarget = mul3(dawnMistCol, dawnLum);
      const dawnMixAmt = clamp(dawnHazeRaw * (0.58 + 0.28 * Math.max(wFog, overcastFactor * 0.6)), 0, 0.88);
      fogCol = mix3(fogCol, dawnFogTarget, dawnMixAmt);

      // Лёгкая кобальтовая подсветка силуэтов деревьев и земли внутри предрассветной дымки
      const dAmbBoost = mul3(dawnMistCol, 0.065 * dawnHazeRaw * dawnLum * (1.0 - 0.35 * storm));
      for (let i = 0; i < 3; i++) amb[i] += dAmbBoost[i];

      groundMist = dawnHaze * clamp(
        (0.72 + 0.55 * wFog + 0.30 * overcastFactor + 0.25 * wSnow + 0.20 * wRain) * (1.0 - 0.25 * storm),
        0.0, 1.45
      );
      mistWarmHor = dawnHaze * (1.0 - wFog * 0.85) * (1.0 - wRain * 0.85) * (1.0 - wSnow * 0.65) * (1.0 - overcastFactor * 0.35);
    }

    // Рассветная дымка (лёгкий тёплый подтон зимой у самого горизонта)
    if (winterDawn > 0.01) {
      fogCol = mix(fogCol, lin3([1.00, 0.72, 0.52]), winterDawn * 0.45 * clearSkyFactor);
    }

    // Холодный фильтр (например, ледяной туман / изморозь)
    if (coldTint > 0.01) {
      fogCol = mix(fogCol, lin3([0.70, 0.82, 0.95]), coldTint * 0.45 * (1.0 - night * 0.6));
    }

    const overcastHaze = overcastFactor * 0.18;
    const horDim = smooth(-4.0, 0.0, altD) * (1.0 - smooth(2.5, 8.5, altD));
    if (horDim > 0.001) {
      fogCol = mul3(fogCol, lerp(1.0, isFog ? 0.82 : 0.72, horDim));
    }
    const rainHaze = wx.rain > 0 ? (0.25 * wx.rain + 1.15 * Math.pow(wx.rain, 1.8)) : 0;
    const snowHaze = wx.snow > 0 ? (0.45 * wx.snow + 0.55 * Math.pow(wx.snow, 1.5)) : 0;
    const dawnDenAdd = dawnHaze * (0.34 + 0.22 * overcastFactor + 0.38 * wFog + 0.14 * Math.max(wRain, wSnow));

    const fogDenNum = 0.05 + 1.10 * wx.fog + rainHaze + snowHaze
                    + overcastHaze + (wx.blizzard ? 0.45 : 0.0) + dawnDenAdd;
    const fogDen = fogDenNum / Math.max(p.diag, 100);

    // ---- 5. Итоговая ночная экспозиция ----
    const nightExposureBoost = lerp(1.68, 0.65, gray * (nCfg ? nCfg.weather.weatherDarkness : 0.65));
    const finalExposure = lerp(1.0, nightExposureBoost, night) * (1.0 - 0.35 * storm);


    const baseEnv = {
      sunDir, sunAltDeg: altD, ldir, lcol, lint, amb, gnd, top, hor, fogCol, fogDen, night,
      isMorning, discRed,
      groundMist, mistWarmHor,
      exposure: finalExposure,
      moon, cloud, fog: wx.fog, wet: wx.wet, snowCover: wx.snowCover,
      rain: wx.rain, snowfall: wx.snow, thunder: wx.thunder,
      ice: (wx.ice || (wx.temp != null && wx.temp < -4)) ? 1 : 0,
      windK: p.isManualWind ? p.windK : (p.windK * (wx.blizzard ? 2.5 : 1.0)),
      wind: (p.windDirDeg != null)
        ? [-Math.sin(p.windDirDeg * DEG), Math.cos(p.windDirDeg * DEG)]
        : [0.93, 0.37]
    };

    return (WM.atmoDev && WM.atmoDev.applyToEnv)
      ? WM.atmoDev.applyToEnv(baseEnv, altD, isMorning, wx)
      : Object.assign(baseEnv, { atmo: makeDefaultAtmoVecs() });
  }


  // ===========================================================================
  // 11. МОДУЛЬНЫЕ ШЕЙДЕРЫ (быстрая компиляция, минимальный код)
  // ===========================================================================
  const GLSL_HEAD = '#version 300 es\nprecision highp float;\nprecision highp int;\nprecision highp sampler2D;\n';

