          const cx = Math.sin(ph) * Math.cos(th) * rx * rr, cy_ = Math.cos(ph) * ry * rr * (f.flatTop ? Math.sign(Math.cos(ph) || 1) * 0.5 : 1), cz = Math.sin(ph) * Math.sin(th) * rz * rr;
