        const fLog = gl.getShaderInfoLog(bd.sf);
        const pLog = gl.getProgramInfoLog(p);
        console.error(`[Slice3D] Ошибка программы «${bd.name}»:\nVS: ${vLog}\nFS: ${fLog}\nLink: ${pLog}`);
        throw new Error(`Ошибка сборки шейдера «${bd.name}»: ${pLog || vLog || fLog}`);
