  const deepMerge = (a, b) => { for (const k in b) { if (b[k] && typeof b[k] === 'object' && !Array.isArray(b[k]) && a[k] && typeof a[k] === 'object') deepMerge(a[k], b[k]); else a[k] = b[k]; } return a; };
  const loadST = () => { try { return deepMerge(JSON.parse(JSON.stringify(DEF)), JSON.parse(localStorage.getItem(LSK + 'st') || '{}')); } catch (e) { return JSON.parse(JSON.stringify(DEF)); } };

