      f[268] = cv('skyScale');  f[269] = cv('skySpeed');   f[270] = cv('skyBias');   f[271] = cv('skySoft');
      f[272] = cv('skyBright'); f[273] = cv('skyShade');   f[274] = cv('skySilver');
      f[275] = (ST.view.clouds !== false) ? cv('skyCirrus') : 0.0;
