      f[328] = at.venusBeltCol[0];    f[329] = at.venusBeltCol[1];    f[330] = at.venusBeltCol[2];    f[331] = at.venusBeltInt;
      f[332] = at.alpenCol[0];        f[333] = at.alpenCol[1];        f[334] = at.alpenCol[2];        f[335] = at.alpenInt;
      f[336] = at.skyHorPow;          f[337] = at.atmoOverride;       f[338] = at.sunHazePass;       f[339] = at.preDawnInt;
      f[340] = at.mistCol[0];         f[341] = at.mistCol[1];         f[342] = at.mistCol[2];         f[343] = at.mistColMix;
      f[344] = sim.squall || 0;
       f[345] = sim.rainLenMul || 1.0;
       f[346] = sim.rainWidthMul || 1.0;
