// ===========================================================================
// СИНТЕТИЧЕСКИЙ РЕЛЬЕФ ДЛЯ АЭРОДИНАМИЧЕСКИХ ТЕСТОВ ОБЛАКОВ
// ===========================================================================
function generateAerodynamicTestDEM(Nx, Ny, W, H) {
  const data = new Float32Array(Nx * Ny);
  const cx = 0.0, cz = 0.0; // Центр преграды
  const span = Math.max(W, H);

  for (let j = 0; j < Ny; j++) {
    const pz = (j / (Ny - 1) - 0.5) * H;
    for (let i = 0; i < Nx; i++) {
      const px = (i / (Nx - 1) - 0.5) * W;

      // 1. Левый главный пик (высокий скалистый массив)
      const d1 = Math.hypot(px - (-span * 0.16), pz - (-span * 0.05));
      const peak1 = Math.exp(-Math.pow(d1 / (span * 0.14), 2.0)) * 520.0;

      // 2. Правый пик (круглый монолитный купол)
      const d2 = Math.hypot(px - (span * 0.18), pz - (span * 0.02));
      const peak2 = Math.exp(-Math.pow(d2 / (span * 0.15), 1.8)) * 440.0;

      // 3. Седловина / перевал между пиками (высота ~180м)
      const dCol = Math.hypot(px, pz);
      const colPass = Math.exp(-Math.pow(dCol / (span * 0.22), 2.2)) * 190.0;

      // 4. Глубокий каньон / ущелье на выходе
      const canyon = (1.0 - Math.exp(-Math.pow(px / (span * 0.06), 2.0))) * 80.0;

      // 5. Мелкие складки и уступы
      const micro = Math.sin(px * 0.015) * Math.cos(pz * 0.015) * 14.0;

      const idx = j * Nx + i;
      data[idx] = Math.max(0.0, Math.max(peak1, peak2) + colPass - canyon + micro + 50.0);
    }
  }

  let hMin = 1e9, hMax = -1e9;
  for (let i = 0; i < data.length; i++) {
    if (data[i] < hMin) hMin = data[i];
    if (data[i] > hMax) hMax = data[i];
  }
  return { data, hMin, hMax };
}

